// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":33,"question":"سائل يقول: في حالة الصلاة في المسجد والجماعة راكعون، هل يصح أن أركع وأنا بعيد عن الجماعة، وليس بجانبي أحد، وبعد أن أعتدل أتقدم حتى أصل إلى الصف مع الجماعة؟","title":"ماذا يفعل من دخل المسجد والإمام راكعٌ؟","answer":"الجواب: هذا وقع لبعض الصحابة ، وهو أبو بكرة الثقفي رضي الله عنه، فإنه جاء ذات يومٍ والنبي عليه الصلاة والسلام راكع، فركع دون الصف، ثم مشى ودخل في الصف، فلما سلم النبي ﷺ سأل عن ذلك، كأنه أحس بذلك، وكان يرى من خلفه ﷺ، كان من خصائصه أنه يرى مَن خلفه عليه الصلاة والسلام، فقال له النبي ﷺ: زادك الله حرصًا ولا تَعُدْ نهاه أن يعود إلى الركوع دون الصف. فدل ذلك على أن الواجب الصبر، حتى تدخل في الصف، وليس لك أن تركع وحدك، فاصبر حتى تصل إلى الصف، وتسد الفرجة، أو إلى طرف الصف وتصف مع الناس، وليس لك أن تصلي وحدك، ولا أن تركع وحدك، بل تصبر حتى يوجد معك أحد، أو تلتمس فُرجة من الصف، أو في طرف الصف، فتدخل في ذلك.","link":"https://binbaz.org.sa/fatwas/2813/ماذا-يفعل-من-دخل-المسجد-والامام-راكع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0006.mp3","categories":["الركوع والسجود"]},{"id":34,"question":"أين يضع المصلون أيديهم بعد الركوع؟","title":"أين يضع المصلي يديه بعد الركوع؟","answer":"الجواب: السُّنة أن توضع الأيدي على الصدر، قبل الركوع وبعده، قال النبي ﷺ في الحديث الصحيح، فيما روى مسلم في صحيحه عن وائل قال: كان النبي ﷺ يضع يده اليمنى على كفه اليُسرى .\nوقال سهل بن سعد : كان الرجل يؤمر أن يضع يده اليمنى على ذراعه اليسرى في الصلاة.\nوفي مسند أحمد وغيره عن أحد الصحابة: أنه رأى النبي ﷺ وضع يديه على صدره في الصلاة.\nوقال وائل: رأيت النبي ﷺ يضع يديه على صدره في الصلاة.\nفهذه هي السُّنة؛ أن يضعهما على صدره وهو قائم في الصلاة، قبل الركوع وبعده، لا فرق في ذلك؛ لأن وائلاً قال: رأيت النبي ﷺ إذا كان قائماً في الصلاة، وضع يمينه على شماله على صدره في الصلاة.","link":"https://binbaz.org.sa/fatwas/2814/اين-يضع-المصلي-يديه-بعد-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0007.mp3","categories":["الركوع والسجود"]},{"id":876,"question":"هل بين السَّجدتين إشارة بالأصبع؟ مع ورود أحاديث من ذلك إن كانت هناك أحاديث.","title":"هل تُشرع إشارة الأصبع بين السجدتين؟","answer":"الجواب: المحفوظ في التَّشهدين الإشارة بالأصبع في التشهدين.\nأما ما رُوي بين السَّجدتين: فالذي يظهر لي أنه شاذٌّ مخالفٌ للأحاديث الصَّحيحة، المروي عن وائلٍ بسندٍ لا بأس به بين السَّجدتين، لكن فيما يظهر أنه شاذٌّ؛ لأنَّ الثقة إذا خالف الثِّقات صار خبرُه شاذًّا، فالمعروف في الأحاديث الصَّحيحة أنَّ بين السَّجدتين يبسط يديه على فخذيه وركبتيه، وليس محلّ إشارةٍ، وإنما الإشارة في التَّشهدين، هذا هو المحفوظ من الأحاديث الصَّحيحة.","link":"https://binbaz.org.sa/fatwas/20925/هل-تشرع-اشارة-الاصبع-بين-السجدتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0720هل بين السجدتين أشارة بالأصبع؟ ابن باز فتاوى المحاضرات.mp3","categories":["الركوع والسجود"]},{"id":897,"question":"كيف تجلس المرأةُ في الصلاة بين السَّجدتين، وكذلك عند الجلوس للتّحيات؟","title":"كيف تجلس المرأةُ في الصلاة بين السَّجدتين؟","answer":"الجواب: مثل الرجل سواء، الرسول قال: صلُّوا كما رأيتُموني أُصلِّي، هذا هو الصواب، أما قول مَن قال: إنها لها صفةٌ أخرى، فلا، الصواب أنها كالرجل في جلوسها، وفي قراءتها، وفي كل شيءٍ، إلا أن تخفض صوتَها إذا كان عندها رجالٌ في الجهرية، تخفض صوتَها خشية الفتنة، وإلا فهي كالرجل: تجلس على رجلها اليسرى بين السَّجدتين، وفي التشهد الأول، وتورك في التشهد الأخير، وترفع يديها عند الإحرام، والركوع، والرفع منه، وعند القيام من التشهد الأول، وتضع يدها اليمنى على كفِّها اليسرى على صدرها في الصلاة كالرجل.","link":"https://binbaz.org.sa/fatwas/20929/كيف-تجلس-المراة-في-الصلاة-بين-السجدتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0725كيف تجلس المرأة في الصلاة بين السجدتين؟ ابن باز فتاوى المحاضرات.mp3","categories":["الركوع والسجود"]},{"id":986,"question":"ما الصحيح في  وضع اليد على الصدر عند الرفع من الركوع؟","title":"ما موضع اليدين بعد الرفع من الركوع؟","answer":"الجواب: هذا هو الصحيح، السُّنة أنَّ المصلي يضع يمينه على شماله على صدره قبل الركوع وبعده. وقال بعضُ أهل العلم: تحت السرة، وقال بعضُهم: فوق السرة. والأمر في هذا واسعٌ وسهلٌ، لا ينبغي فيه النزاع والخلاف والمعاداة، ينبغي في هذا التَّسامح؛ لأن العلماء اختلفوا في هذا: منهم مَن يقول: تحت السرة، ومنهم مَن يقول: فوق السرة، ومنهم مَن يقول: فوق الصدر، وقد يقع بين بعض الناس نزاعٌ في هذا وتهاجر، لا ينبغي، لكن الأفضل فوق السرة، هذا هو الذي جاءت به الأحاديثُ الجيدة: فوق السرة؛ لحديث قبيصة بن هلب الطائي عن أبيه، وحديث وائل بن حُجْر، وإن كان فيه بعض اللِّين، لكن يشهد له حديث قبيصة، وجاء في حديثٍ مرسل صحيح عن طاووس، يعضد بعضُها بعضًا، وهي قوية.\nفالأفضل على الصدر، ولو وضعها على السرة لفتوى أهل بلاده، أو يخاف من شرٍّ يقع بينه وبين أهل بلاده؛ فلا بأس، الأمر في هذا واسعٌ، لا ينبغي في هذا التَّشديد والمعاداة.","link":"https://binbaz.org.sa/fatwas/21022/ما-موضع-اليدين-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0819ما هو الصحيح في وضع اليدعند الرفع من الركوع؟ ابن باز فتاوى المحاضرات.mp3","categories":["الركوع والسجود"]},{"id":1025,"question":"ما حكم زيادة كلمة \"الشكر\" في قولنا: ربنا لك الحمد؟","title":"ما حكم زيادة \"الشكر\" بعد الرفع من الركوع؟","answer":"الجواب: المعروف في الأحاديث أنه ﷺ كان إذا رفع رأسه من الركوع قال: سمع الله لمن حمده، ثم قال بعدها: ربنا ولك الحمد، وربما قال: ربنا لك الحمد، وربما قال: اللهم ربنا لك الحمد، وربما قال: اللهم ربنا ولك الحمد أربع روايات، أربع صفات جاءت بها النصوص، والمنفرد والمأموم كذلك يقول هذا: ربنا ولك الحمد، أو: ربنا لك الحمد، أو: اللهم ربنا لك الحمد، أو: اللهم ربنا ولك الحمد، إلى آخره: حمدًا كثيرًا طيبًا مُباركًا فيه، ملء السَّماوات، وملء الأرض، وملء ما بينهما، وملء ما شئتَ من شيءٍ بعد، وإن زاد قال: أهل الثناء والمجد، أحقّ ما قال العبدُ، وكلنا لك عبدٌ، لا مانع لما أعطيتَ، ولا مُعطي لما منعتَ، ولا ينفع ذا الجدِّ منك الجدّ.\nهذا مشروعٌ للمؤمن والمؤمنة، والإمام والمنفرد والمأموم، كلهم مشروعٌ لهم هذا، لكن الإمام والمنفرد يبدآن بـ سمع الله لمن حمده، ثم يقولان: ربنا ولك الحمد، أما المأموم فيقول: ربنا ولك الحمد من حين أن يرفع رأسه من الركوع، يقول: ربنا ولك الحمد، أو اللهم ربنا لك الحمد.\nأما كلمة \"والشكر\" فما أعرف لها أصلًا، ولكن هي بمعنى الحمد؛ لأنَّ الحمد معناه الشكر والثناء، فإذا أطلق الحمدَ دخل فيه الشكر، فالشكر هو الثناء على الله بالقول والعمل، فلا حاجةَ إليه، داخلٌ في قوله: ربنا ولك الحمد، ولو قالها إنسانٌ ما تضرُّ صلاته، ولا حرج فيها، لكن تركها أوْلى؛ لأنها لم ترد، وإلا فهي داخلةٌ في معنى الحمد، لكن المؤمن لا يأتي بشيءٍ من كيسه، تركها أوْلى، فيقتصر على قوله: ربنا ولك الحمد ويكفي، ولا يحتاج إلى زيادة: \"والشكر\"؛ لأنها لم ترد في النصوص فيما نعلم، وإن كانت داخلةً في معنى الحمد، لكن المؤمن يكون مع النصوص، والعبادات توقيفية، فالأفضل للمؤمن أن يقول: ربنا ولك الحمد فقط من دون زيادة \"والشكر\" إذا رفع من الركوع، بعض العامَّة يقول هذه الكلمة، لكن لا تضرُّ صلاته، لكن يُوجَّه ويُعلَّم أنَّ الأفضل تركها؛ لأنها لم ترد.","link":"https://binbaz.org.sa/fatwas/21072/ما-حكم-زيادة-الشكر-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0868ما حكم زيادة كلمة الشكر في قولنا ربنا ولك الحمد بعد الرفع من الركوع؟ ابن باز فتاوى المحاضرات.mp3","categories":["الركوع والسجود"]},{"id":1209,"question":"ما حكم السُّجود على العمامة أو الطاقية؟","title":"ما حكم السُّجود على العمامة أو الطاقية؟","answer":"الجواب:\nلا حرج في ذلك، لكن تركه أفضل، يسجد على المصلَّى، يرفع العمامة والطاقية ويسجد على المصلى، هذا هو الأفضل، وإن سجد على العمامة أو الطاقية أو غيرهما صحَّ السجود، لكن كونه يرفع العمامة ويرفع الطاقية بحيث يُباشر المصلَّى أفضل، كما كان النبيُّ يفعل عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/21260/ما-حكم-السجود-على-العمامة-او-الطاقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1134ما حكم السجود على العمامة أو الطاقية؟ ابن باز فتاوى.mp3","categories":["الركوع والسجود"]},{"id":2089,"question":"إذا غلب المأمومَ النومُ في أثناء السّجود؟","title":"ما حكم مَن غلبه النُّعاس في السجود؟","answer":"الجواب:\nهذا يُسَمَّى نُعاسًا، وهو يَعْرض للناس، ولا يضرّ.","link":"https://binbaz.org.sa/fatwas/22207/ما-حكم-من-غلبه-النعاس-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من غلبه النعاس في السجود.mp3","categories":["الركوع والسجود"]},{"id":2599,"question":"رجل يضع جبهته على الأرض دون الأنف في السجود، وربما لم يمكن جبهته على الأرض، فما حكم صلاته؟","title":"حكم عدم تمكين الأنف والجبهة في السجود","answer":"الجواب: لا بدّ من تمكين الجبهة والأنف، ولا يصح السجود إلا بذلك، فإذا تعمّد هذا بطلت صلاته. وإذا كان عن سهو تبطُل الركعة التي تركه منها وتقوم الأخرى مقامها، ويأتي بركعة أخرى إذا كان فردًا، وإذا كان مأمومًا إذا سلم إمامه يأتي بركعة؛ لأنه ضيع ركعة.\nس: إذا لم يمس أنفه الأرض طوال السجود أم إذا مسه في جزء من أجزاء السجود؟\nالشيخ: لا بدّ أنه يسجد على الأنف والجبهة جميعًا، لا بد منهما جميعا، كان النبي ﷺ يسجد على الجبهة والأنف ويقول: أُمرت أن أسجد على سبعة أعْظُم: على الجبهة.. وأشار إلى أنفه.","link":"https://binbaz.org.sa/fatwas/22732/حكم-عدم-تمكين-الانف-والجبهة-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من لا يضع أنفه في السجود أو يمكن جبهته على الأرض.mp3","categories":["الركوع والسجود"]},{"id":2899,"question":"التعظيم الذي ورد في الركوع يُفسّر بقوله: سبحان ربي العظيم، أو يشمل جميع أنواع التعظيم، مثل لو عظّم الله من دون أن يسبّح في الركوع بعد الإتيان بالذكر الوارد؟","title":"معنى تعظيم الرب عز وجل في الركوع","answer":"الجواب: معناه أنه يتحرى التسبيحات التي فيها تعظيم الرب، ما هي بدعاء: سُبُّوحٌ قُدُّوس، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، سبحان ربي العظيم، سبحان ربي العظيم.  يعني هو محل انكسار لكن بين السجود وبين القيام فيكون التهليلات التي فيه بين هذا وهذا، فهو في حالة انكسار وذل، ولكنه دون السجود، السجود أكثر خضوعًا وأكثر ذلًّا؛ فلهذا صار الدعاء فيه أعظم وأكثر وأبلغ.","link":"https://binbaz.org.sa/fatwas/23054/معنى-تعظيم-الرب-عز-وجل-في-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعظيم الرب عز وجل في الركوع.mp3","categories":["الركوع والسجود"]},{"id":2907,"question":"حديث عائشة رضي الله عنها بأنها وجدت قدمي النبي ﷺ منصوبتان: أليس فيه دلالة على جمع القدمين في حال السجود؟","title":"حكم وكيفية نصب القدمين في حال السجود","answer":"الجواب: السنة نَصْبُهما حال السجود، يعتمد على بطون الأصابع.\nس: مع التفريق أو مع الجمع؟\nالشيخ: هذا الأصل التفريق؛ لأن الرسول ﷺ كان يفرّق بين ركبتيه وقدميه ويديه، عليه الصلاة والسلام، في سجوده وفي ركوعه، اللهم صل عليه وسلم. أما رواية أن إحدى عقبيه على الآخر: فيها نظر، من رواية ابن خزيمة والحاكم، والأصل في هذا كله: عدم الضَّم، الأصل: بسط الأعضاء وعدم ضمها، هكذا جاءت السنة الصحيحة.\nس: تعتبر شاذة؟\nالشيخ: محتمل، مقتضى القواعد أنها شاذة.","link":"https://binbaz.org.sa/fatwas/23063/حكم-وكيفية-نصب-القدمين-في-حال-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نصب القدمين في حال السجود.mp3","categories":["الركوع والسجود"]},{"id":3491,"question":"الصواب في قبض الأصابع في الجلسة بين السجدتين، وتحريك السبابة؟","title":"ما السُّنة في هيئة الأصابع بين السجدتين؟","answer":"الجواب: السنة في التشهد، أما بين السجدتين يضعهما على فخذيه، أو على ركبتيه، هذه رواية وفي صحتها نظر؛ لأنها مخالفة للأحاديث الصحيحة.\nس: ما يُقال إن السنة أحيانًا قبض الأصابع؟\nالشيخ: المعروف في الحديث الصحيح أنها تبسط على الفخذين والركبتين بين السجدتين، أما في التشهد فيشير بالسبابة.","link":"https://binbaz.org.sa/fatwas/23669/ما-السنة-في-هيىة-الاصابع-بين-السجدتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قبض الأصابع في الجلسة بين السجدتين، وتحريك السبابة.mp3","categories":["الركوع والسجود"]},{"id":3571,"question":"دعاء اللهم باعد بيني وبين خطاياي، هل يقال بعد الرفع من الركوع؟","title":"هل وَرَدَ بعد الركوع: اللهم نقني من خطاياي؟","answer":"الجواب: جاء بعد الركوع: اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد هكذا جاء بعد الركوع أيضًا.","link":"https://binbaz.org.sa/fatwas/23753/هل-ورد-بعد-الركوع-اللهم-نقني-من-خطاياي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقال بعد الرفع من الركوع اللهم باعد بيني وبين خطاياي.mp3","categories":["الأدعية والأذكار","الركوع والسجود"]},{"id":3578,"question":"إذا رفع من السجود يكبر ويرفع يديه؟","title":"هل تُرفع اليدين عند الرفع من السجود؟","answer":"الجواب: يكبر بس، بدون رفع اليدين.","link":"https://binbaz.org.sa/fatwas/23760/هل-ترفع-اليدين-عند-الرفع-من-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تُرفع اليدين عند الرفع من السجود.mp3","categories":["الركوع والسجود"]},{"id":3581,"question":"لم يقل له الرسول ﷺ قل سبحان ربي العظيم سبحان ربي الأعلى، فهل يكون من وضع سبحان ربي العظيم مكان سبحان ربي الأعلى ليس عليه شيء؟","title":"حكم قول ذكر الركوع في السجود والعكس","answer":"الجواب: لا، جاءت في النصوص الأخرى، النصوص يُجمع بينها، جاء من فعله ﷺ قال: صلوا كما رأيتموني أصلي وجاء في بعض الروايات: إذا ركع يقول: سبحان ربي العظيم.","link":"https://binbaz.org.sa/fatwas/23763/حكم-قول-ذكر-الركوع-في-السجود-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من وضع سبحان ربي العظيم وسبحان ربي الأعلى.mp3","categories":["الأدعية والأذكار","الركوع والسجود"]},{"id":3582,"question":"إذا دخل المأموم مع الإمام قبل ركوع الإمام ولكن لم يركع حتى رفع الإمام من الركوع لاشتغاله بقراءة الفاتحة فهل يَعتدّ بالركعة أم يقضي ولا يَعتدّ بها؟","title":"متى يُعتدّ بالركوع مع الإمام؟","answer":"الجواب: الظاهر أنه لا يعتد بالركعة، فاته الركوع، ركع الإمام ورفع وهو متعمد.\nس: إذا رفع الإمام من الركوع ونسي أو تأخر في التسميع فتأخر مأموم ورأى الإمام قد رفع وجماعة ركوع ثم ركع معهم هل يَعتد بالركعة؟\nالشيخ: إذا كان الإمام قد رفع لا يَعتد بالركعة.\nس: لكنه ما سَمَّع، تأخر بالتسميع، يعني رفع ولم يقل سمع الله لمن حمده، تأخر قليلاً؟\nالشيخ: المقصود إذا كان رفع من الركوع قبل أن يركع المأموم لا يَعتد بها.\nس: ولو كان الجماعة في الركوع؟\nالشيخ: ولو، العبرة ركوع الإمام.\nس: من ركع الإمام ولكن لم يستطع أن يقول ولا مرة: سبحان ربي العظيم.\nالشيخ: إذا استوى راكعًا ثم سبح بعدها أجزأته؛ لأنه تم له الركوع.","link":"https://binbaz.org.sa/fatwas/23764/متى-يعتد-بالركوع-مع-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في متى يعتد الركوع مع الإمام.mp3","categories":["الركوع والسجود"]},{"id":3583,"question":"يجوز الدعاء في الركوع كالسجود؟","title":"ما حكم الدعاء في الركوع؟","answer":"الجواب: الركوع فيه تعظيم: أما الركوع فعظموا فيه الرب لكن دعاء تابع لا بأس سبحانك اللهم ربنا وبحمدك اللهم اغفر لي هذا تابع، الرسول ﷺ قال: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء.\nس: يعني لا يدعو بأمر من أمور الدنيا؟\nالشيخ: لا، يعظّم الرب سبحان ربي العظيم، سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، سبوح قدوس، إلى آخره.","link":"https://binbaz.org.sa/fatwas/23765/ما-حكم-الدعاء-في-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء في الركوع كالسجود.mp3","categories":["الركوع والسجود","الأدعية والأذكار"]},{"id":3591,"question":"بعض المصلين ربما يرفع رجليه في السجود؟","title":"حكم صلاة من يرفع رجليه في السجود","answer":"الجواب: إذا صلى يعتمد على أصابعه لا بدّ، لا يرفع، إذا رفعها ما صح السجود، لا بد يعتمد على بطون أصابع رجليه.","link":"https://binbaz.org.sa/fatwas/23773/حكم-صلاة-من-يرفع-رجليه-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع الرجلين في السجود.mp3","categories":["الركوع والسجود"]},{"id":3595,"question":"من لم يسجد على الأنف سجوده صحيح؟","title":"هل سجود من لم يسجد على الأنف صحيح؟","answer":"الجواب: لا، حتى يسجد على الأنف، الجبهة والأنف عضو واحد وهو أحد الأعضاء السبعة.","link":"https://binbaz.org.sa/fatwas/23777/هل-سجود-من-لم-يسجد-على-الانف-صحيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل سجود من لم يسجد على الأنف صحيح.mp3","categories":["الركوع والسجود"]},{"id":4564,"question":"يضم القدمين عند السجود؟","title":"ما حكم ضمُّ القدمين عند السجود؟","answer":"الجواب: الصواب: لا، ينصبهما ويُفرِّقهما، هذا المحفوظ، أما رواية ابن خزيمة والحاكم ففيها نظر، فيها ضعف ..... منصوبتان، هذا هو الأفضل، كما في رواية مسلم.\nس: يُفرِّق بينهما؟\nج: نعم، ينصبهما ويُفرِّق بينهما.","link":"https://binbaz.org.sa/fatwas/24846/ما-حكم-ضم-القدمين-عند-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضمُّ القدمين عند السجود.mp3","categories":["الركوع والسجود"]},{"id":4565,"question":"إذا قال: لربي الحمد، لربي الحمد، دون أن يقول غيرها من الصِّفات الأربع؟","title":"حكم قول \"لربي الحمد\" عند الرفع من الركوع","answer":"الجواب: عند الرفع يعني؟\nس: نعم.\nج: لا عليه شيء، لكن الأفضل المعروف في الأحاديث الصحيحة: \"ربنا ولك الحمد\"، \"اللهم ربنا لك الحمد\"، ينبغي له أن يُلاحظ الأحاديث الصَّحيحة.","link":"https://binbaz.org.sa/fatwas/24848/حكم-قول-لربي-الحمد-عند-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول لربي الحمد عند الرفع من الركوع.mp3","categories":["الركوع والسجود"]},{"id":4566,"question":"قوله: \"سبحان الله وبحمده\"؟","title":"حكم \"سبحان الله وبحمده\" في الركوع والسجود","answer":"الجواب: في الركوع والسجود؟\nس: نعم.\nج: لا بأس، لكن المعروف \"سبحان ربي العظيم\"، وإذا قال: \"سبحان الله وبحمده\" جاز مثلما قال النبيُّ ﷺ.\nس: سبحان الله العظيم وبحمده؟\nج: لا بأس، لكن تركها أفضل، \"سبحان ربي العظيم، سبحان ربي العظيم\"؛ لأنَّ في ثبوتها نظرًا عند أهل الحديث، أسانيدها ضعيفة، ولو قالها ما يضرّ؛ لأنها موجودة في قوله: \"سبحانك اللهم ربنا وبحمدك ..\" في الحديث الصحيح، فالأمر فيها واسع، وفي الصحيح عن عائشة: كان يُكثر أن يقول في الركوع والسجود: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، هذا في الصحيح عن عائشة رضي الله عنها.","link":"https://binbaz.org.sa/fatwas/24849/حكم-سبحان-الله-وبحمده-في-الركوع-والسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول سبحان الله وبحمده أو سبحان الله العظيم وبحمده في الركوع والسجود.mp3","categories":["الركوع والسجود"]},{"id":4581,"question":"إذا سجد على ثوبه؟","title":"حكم السجود على الثوب","answer":"الجواب: ما يضرّ، إذا سجد على ثوبه ما في بأس.\nس: إذا سجد على شوكٍ؟\nج: إذا كان ما يُؤذيه، بعض الناس جبهته خشنة، إذا كان ما يُؤذيه فلا بأس.\nس: هل يرفع رأسه ويُزيل هذا الشيء ويرجع للسجود؟\nج: نعم، يرفع رأسه ويُزيل ما أذاه ثم يضع رأسه –جبهته.\nس: السجود على وسادةٍ؟\nج: الأفضل في الهواء، إذا كان يعجز فلا يحط وسادةً ولا غيرها يُومئ إيماءً إذا عجز عن السجود.","link":"https://binbaz.org.sa/fatwas/24867/حكم-السجود-على-الثوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السجود على الثوب أو الشوك أو الوسادة.mp3","categories":["الركوع والسجود"]},{"id":4863,"question":"يسأل السائل عن الدّعاء بين السَّجدتين لو تركه المُصلي عامدًا، فما حُكم صلاته؟","title":"حكم صلاة من ترك الدّعاء بين السَّجدتين عمدًا","answer":"الصواب أنها تبطل؛ لأنه واجبٌ، الرسول أمر به فقال: صلُّوا كما رأيتُموني أُصلي، فإذا ما قال: \"ربِّ اغفر لي\" بين السَّجدتين عامدًا، وهو يعلم الحكم، ما هو بجاهلٍ؛ تبطل صلاته، أما إذا كان جاهلًا أو ناسيًا فما عليه شيء، لكن إذا كان إمامًا أو مُنفردًا وهو ناسٍ يسجد للسهو، أما إذا كان تبع الإمام ما عليه شيء.","link":"https://binbaz.org.sa/fatwas/25335/حكم-صلاة-من-ترك-الدعاء-بين-السجدتين-عمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ترك الدّعاء بين السَّجدتين عمدًا.mp3","categories":["الركوع والسجود","الأدعية والأذكار"]},{"id":5751,"question":"سبب اختيار الإمام أحمد -رحمه الله- لدعاء الاستفتاح: سبحانك اللهم وبحمدك إلى آخره، مع أن هذا حديث منقطع كما قال المحدثون، ومن المعلوم أن الإمام أحمد ترك الأحاديث الصحيحة في ذلك؟","title":"سبب اختيار الإمام أحمد دعاء الاستفتاح «سبحانك اللهم وبحمدك..»","answer":"الجواب:  الحديث منقطع من طريق عمر، ولكنه جاء من طريق آخر، المنقطع من طريق عمر، ولكنه جاء من طريق عائشة، وأبي سعيد الخدري ..[وأبي هريرة].  وهو دعاء مختصر جدًا، ومحض في ذكر الله  فلهذا استحبه من استحب أن ... لكونه خالص بذكر الله ما فيه دعاء كله ذكر لله، وكله قائم لله؛ ولأنه مختصر ويحفظه الناس قليل.  ولهذا استحبه أحمد وغيره بغير إنكار للاستفتاحات الأخرى، فهو استفتاح موجز مختصر، جاء فيه عدة أحاديث، فلهذا استحبه جماعة من أهل العلم لاختصاره، وكونه محضًا للذكر، وتوحيد الله  وإذا استفتح بغيره مثل: اللهم باعد بيني وبين خطاياي اللهم رب جبرائيل وميكائيل..  إلى آخره فكله طيب، والأفضل أن يستفتح بهذا تارة، وهذا تارة، وهذا تارة حتى يكون جمع بين الاستفتاحات. وأسأل الله أن يوفق الجميع لمراضيه، وأن يوفقنا وإياكم للعلم النافع، والعمل الصالح، وأن يتقبل منا جميعًا، وصلى الله على نبينا محمد وعلى آله وصحبه.","link":"https://binbaz.org.sa/fatwas/1073/سبب-اختيار-الامام-احمد-دعاء-الاستفتاح-سبحانك-اللهم-وبحمدك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_85.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":5767,"question":"سبب اختيار الإمام أحمد -رحمه الله- لدعاء الاستفتاح: سبحانك اللهم وبحمدك إلى آخره، مع أن هذا حديث منقطع كما قال المحدثون، ومن المعلوم أن الإمام أحمد ترك الأحاديث الصحيحة في ذلك؟","title":"سبب اختيار الإمام أحمد دعاء الاستفتاح «سبحانك اللهم وبحمدك..»","answer":"الجواب:  الحديث منقطع من طريق عمر، ولكنه جاء من طريق آخر، المنقطع من طريق عمر، ولكنه جاء من طريق عائشة، وأبي سعيد الخدري ..[وأبي هريرة].  وهو دعاء مختصر جدًا، ومحض في ذكر الله  فلهذا استحبه من استحب أن ... لكونه خالص بذكر الله ما فيه دعاء كله ذكر لله، وكله قائم لله؛ ولأنه مختصر ويحفظه الناس قليل.  ولهذا استحبه أحمد وغيره بغير إنكار للاستفتاحات الأخرى، فهو استفتاح موجز مختصر، جاء فيه عدة أحاديث، فلهذا استحبه جماعة من أهل العلم لاختصاره، وكونه محضًا للذكر، وتوحيد الله  وإذا استفتح بغيره مثل: اللهم باعد بيني وبين خطاياي اللهم رب جبرائيل وميكائيل..  إلى آخره فكله طيب، والأفضل أن يستفتح بهذا تارة، وهذا تارة، وهذا تارة حتى يكون جمع بين الاستفتاحات. وأسأل الله أن يوفق الجميع لمراضيه، وأن يوفقنا وإياكم للعلم النافع، والعمل الصالح، وأن يتقبل منا جميعًا، وصلى الله على نبينا محمد وعلى آله وصحبه.","link":"https://binbaz.org.sa/fatwas/1073/سبب-اختيار-الامام-احمد-دعاء-الاستفتاح-سبحانك-اللهم-وبحمدك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_85.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":5895,"question":"هل الأفضل أن يقال بعد الرفع من الركوع: ربنا ولك الحمد، أم اللهم ربنا ولك الحمد؟","title":"ما يقال بعد الرفع من الركوع","answer":"الجواب: كله جائز، كله جاء عن النبي ﷺ جاء في هذا أربع جمل : ربنا لك الحمد، بدون واو، ربنا ولك الحمد بالواو، الثالثة: اللهم ربنا لك الحمد، الرابعة: اللهم ربنا ولك الحمد، كلها الأربع جاءت عن النبي ﷺ فإذا استعمل هذه تارة، وهذه تارة فكله طيب، والحمد لله، والأمر واسع، الإمام والمنفرد.","link":"https://binbaz.org.sa/fatwas/1245/ما-يقال-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_241.mp3","categories":["الأدعية والأذكار","الركوع والسجود"]},{"id":5913,"question":"هل الأفضل أن يقال بعد الرفع من الركوع: ربنا ولك الحمد، أم اللهم ربنا ولك الحمد؟","title":"ما يقال بعد الرفع من الركوع","answer":"الجواب: كله جائز، كله جاء عن النبي ﷺ جاء في هذا أربع جمل : ربنا لك الحمد، بدون واو، ربنا ولك الحمد بالواو، الثالثة: اللهم ربنا لك الحمد، الرابعة: اللهم ربنا ولك الحمد، كلها الأربع جاءت عن النبي ﷺ فإذا استعمل هذه تارة، وهذه تارة فكله طيب، والحمد لله، والأمر واسع، الإمام والمنفرد.","link":"https://binbaz.org.sa/fatwas/1245/ما-يقال-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_241.mp3","categories":["الأدعية والأذكار","الركوع والسجود"]},{"id":6283,"question":"ما هو الصحيح من الأحاديث في دعاء السجود، والركوع؟ وما هو أول ما يقع على الأرض بعد الرفع من الركوع؟ وما هي حركة اليد اليمنى بسبابتها في التشهد؟","title":"ما صحيح الدعاء في الركوع والسجود وأول ما يوضع على الأرض؟","answer":"الجواب: إذا ركع المشروع في الركوع تعظيم الرب، قال النبي ﷺ: وأما الركوع فعظموا فيه الرب فيقول: سبحان ربي العظيم، سبحان ربي العظيم، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، اللهم لك ركعت، وبك آمنت، ولك أسلمت، خشع لك سمعي، وبصري، ومخي، وعظمي، وعصبي، وما استقلت به قدمي، كل هذا يقال في الركوع مشروع، والواجب مرة سبحان ربي العظيم، والبقية سنة. والسجود كذلك: سبحان ربي الأعلى، الواجب مرة، والباقي سنة، يكرر ثلاثًا، أو خمسًا، أو سبعًا، ويقول: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، ويدعو في سجوده ما تيسر، النبي كان يدعو في السجود، ويقول -عليه الصلاة والسلام-: وأما السجود فاجتهدوا في الدعاء؛ فقمن أن يستجاب لكم، ويقول -عليه الصلاة والسلام-: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء.  ويقول في حديث علي كان إذا سجد يقول: اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه، وصوره، وشق سمعه، وبصره، فتبارك الله أحسن الخالقين وكان يقول في سجوده: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخرته، وعلانيته وسره.  وأول ما يقع على الأرض الركبتين -على الأصح- ثم اليدين، ثم الجبهة، والأنف، هذا هو أول ما يقع على حديث وائل، أولها الركبتان، ثم اليدان، ثم الجبهة، والأنف، والرفع يرفع أولًا الجبهة، والأنف، ثم يرفع اليدين، ثم ينهض بالركبتين، هذا هو المشروع. وأما حديث أبي هريرة في رفع اليدين قبل الركبتين فهو حديث فيه انقلاب؛ لأن في أوله لا يبرك كما يبرك البعير والبعير يبرك على يديه أولًا، فدل ذلك على أن المصلي لا يبرك على يديه، وإنما يبرك على ركبتيه، ثم يديه. وأما قوله: وليضع يديه قبل ركبتيه، فهذا فيه انقلاب، والأرجح والأظهر أن الرواية: وليضع ركبتيه قبل يديه كما يوافق صدر الحديث؛ لأن صدر الحديث يقتضيه، ويوافق أيضًا حديث وائل في هذا الباب.","link":"https://binbaz.org.sa/fatwas/1811/ما-صحيح-الدعاء-في-الركوع-والسجود-واول-ما-يوضع-على-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_652.mp3","categories":["الأدعية والأذكار","الركوع والسجود"]},{"id":6631,"question":"رجل صلى، ونسي الركوع في إحدى الركعات، ولكنه تذكره حين سجد، فماذا عليه؟","title":"حكم من نسي الركوع ثم تذكره وهو ساجد","answer":"الجواب: عليه أن يرجع فيركع، ثم يسجد سجدتين، ويسجد للسهو بعد ذلك، عليه أن يعود واقفًا، يكبر راكعًا، ثم يرفع، ثم يسجد سجدتين، ثم يتم ... فإن كان ما ذكر إلا الركعة الثانية؛ قامت الثانية مقامها، وبطلت الأولى، وهي التي ترك .. إذا كان ما ذكر إلا في الثانية. أما إن كان ذكر في السجود؛ فإنه عليه أن يرجع، فيقوم، ويكبر راكعًا، ثم يرفع، ثم يسجد إلى آخره، ويكمل صلاته، وعليه سجود السهو بعد ذلك قبل أن يسلم سجدتين، قبل أن يسلم. السؤال: ولو نسي المأموم؟ الجواب: المأموم، يعود، يركع، ويلحق إمامه.","link":"https://binbaz.org.sa/fatwas/2466/حكم-من-نسي-الركوع-ثم-تذكره-وهو-ساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_993.mp3","categories":["سجود السهو","الركوع والسجود"]},{"id":6645,"question":"رجل صلى، ونسي الركوع في إحدى الركعات، ولكنه تذكره حين سجد، فماذا عليه؟","title":"حكم من نسي الركوع ثم تذكره وهو ساجد","answer":"الجواب: عليه أن يرجع فيركع، ثم يسجد سجدتين، ويسجد للسهو بعد ذلك، عليه أن يعود واقفًا، يكبر راكعًا، ثم يرفع، ثم يسجد سجدتين، ثم يتم ... فإن كان ما ذكر إلا الركعة الثانية؛ قامت الثانية مقامها، وبطلت الأولى، وهي التي ترك .. إذا كان ما ذكر إلا في الثانية. أما إن كان ذكر في السجود؛ فإنه عليه أن يرجع، فيقوم، ويكبر راكعًا، ثم يرفع، ثم يسجد إلى آخره، ويكمل صلاته، وعليه سجود السهو بعد ذلك قبل أن يسلم سجدتين، قبل أن يسلم. السؤال: ولو نسي المأموم؟ الجواب: المأموم، يعود، يركع، ويلحق إمامه.","link":"https://binbaz.org.sa/fatwas/2466/حكم-من-نسي-الركوع-ثم-تذكره-وهو-ساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_993.mp3","categories":["سجود السهو","الركوع والسجود"]},{"id":6994,"question":"ما رأيكم في قول الألباني في كتابه \"كيفية صلاة النبي ﷺ\" أن وضع اليمنى على اليسرى على الصدر بعد الركوع بدعة؟ وما رأيكم في قوله: بتقديم اليدين على الركبتين عند السجود؟","title":"حكم وضع اليد اليمنى على اليسرى بعد الركوع","answer":"الجواب:\n\nهذا قد نبهناه عليه، قوله: إن وضع اليدين بعد الركوع بدعة، هذا غلط، ونبهناه عليه، وكتبنا في هذا في الصحف منذ مدة، ووضحنا أن وضع اليدين على الصدر قبل الركوع، أو بعد الركوع سنة، وقوله في صفة صلاة النبي أنه بدعة غلط منه -عفا الله عنا وعنه- ولعله يراجع ذلك؛ لأنه رجل جيد، وطيب، وطالب علم، وله نشاط كبير في الحديث -جزاه الله خيرًا- ولكن له أخطاء، وأغلاط مثل غيره، أنا، وهو، وغيرنا، كل له أغلاط، لكن هذا غلط منه -على كل حال- غلط وضع اليدين بعد الركوع، وهو قائم سنة، مثل وضعها قبل الركوع، سواء سواء.\n\nيقول وائل بن حجر : رأيت النبي ﷺ إذا كان قائمًا في الصلاة يضع يده اليمنى على كفه اليسرى، والرسغ، والساعد، هكذا السنة.\n\nوأما عند السجود: فاختلف العلماء، منهم من يرى وضع اليدين قبل، ومنهم من يرى وضع الركبتين.\n\nوالأرجح: وضع الركبتين قبل حتى لا يشبه البعير في وضع يديه؛ لأن البعير يبدأ بيديه، فالسنة أن تبدأ برجليك، لا بيديك؛ خلافًا للبعير، كما ثبت عن النبي ﷺ أنه كان إذا سجد وضع ركبتيه قبل يديه -عليه الصلاة، والسلام-.","link":"https://binbaz.org.sa/fatwas/2913/حكم-وضع-اليد-اليمنى-على-اليسرى-بعد-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1361.mp3","categories":["سجود السهو","الركوع والسجود"]},{"id":7722,"question":"أيضاً يقول: هل هذا الحديث صحيح: وكان ﷺ يضع يديه على الأرض قبل ركبتيه أخرجه ابن خزيمة و الدارقطني و الحاكم ؟","title":"القول الراجح في صفة النزول للسجود","answer":"الجواب: جاء في الباب أحاديث، بعضها يدل على أنه يضع يديه قبل ركبتيه، وبعضها يدل على أنه يضع ركبتيه قبل يديه، جاء هذا وهذا.\nوالأرجح ما جاء في حديث وائل بن حجر وأنس بن مالك رضي الله عنهما: أن النبي عليه السلام كان يضع ركبتيه قبل يديه ثم يرفع رأسه ثم يديه قبل ركبتيه عند الرفع من السجود هذا هو الأفضل، أما حديث أبي هريرة في أمر وضع اليدين قبل الركبتين، فقد ذكر بعض أهل العلم أن الأقرب فيه أنه مقلوب، وأن الصواب: وليضع ركبتيه قبل يديه هذا هو الأقرب؛ لأنه في أول الحديث نهى عن بروك كبروك البعير، والذي يضع يديه قبل ركبتيه يشبه بروك البعير؛ لأن البعير يضع يديه ثم رجليه.\nفالأفضل للمؤمن أن يضع ركبتيه ثم يديه ثم جبهته وأنفه، وبذلك تجتمع الأخبار، تجتمع أخبار النبي ﷺ حديث أبي هريرة وحديث وائل وحديث أنس وما جاء في معناها، في وضع الركبتين ثم اليدين ثم الجبهة والأنف تجتمع الأخبار، ويتضح أن ما في حديث أبي هريرة من قوله: وليضع يديه قبل ركبتيه الظاهر أنه منقلب على الراوي، وإنما الصواب: وليضع ركبتيه قبل يديه حتى لا يوافق البعير الذي يضع يديه قبل ركبتيه. نعم.","link":"https://binbaz.org.sa/fatwas/4921/القول-الراجح-في-صفة-النزول-للسجود ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03108.mp3","categories":["الركوع والسجود"]},{"id":10093,"question":"هناك حديث للرسول ﷺ يقول فيه فيما يرويه ابن عباس أنه أمر أن يسجد على سبعة أعضاء في الصلاة ولا يكف شعرًا ولا ثوبًا، كيف يكون كف الشعر والثوب، وأنا أثناء الصلاة عندما أريد أن أسجد فإني أرفع البنطلون من ناحية الفخذ ثم أسجد، هل هذا يكون من كف الثياب، وهل كف الثوب والشعر مكروه أم محرم؟","title":"إذا أراد أن يسجد يرفع البنطلون فهل هذا من كف الثوب","answer":"الجواب: الرسول ﷺ قال هذا الكلام، قال: إنه أمر أن يسجد على سبعة أعظم وأن لا يكف شعرًا ولا ثوبًا، فالمعنى أن المصلي إذا أراد أن يسجد وعليه شعر أو وعليه عمامة لا يكفها عن الأرض يسجد وتسجد معه لا يكفها من أجل السجود خوفًا عليها من التراب يسجد بها هذا المعنى سواء كانت عمامة أو بشتًا أو رداءً أو غير ذلك أو بنطلونًا أو غيره يسجد عليه ويترك أطرافة تسجد في الأرض. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8262/اذا-اراد-ان-يسجد-يرفع-البنطلون-فهل-هذا-من-كف-الثوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33306.mp3","categories":["الركوع والسجود"]},{"id":10250,"question":"تقول أختنا: ذكر النووي في كتاب الأذكار: أنه يستحب أن لا يجمع بين جميع الأدعية الواردة عن رسول الله صلى الله عليه وسلم في دعاء الاستفتاح أو في الركوع فما هو رأي سماحتكم؟","title":"حكم الجمع بين أكثر من دعاء وارد في الاستفتاح","answer":"الجواب: السنة أن ينوع في الاستفتاح، ما كان النبي يجمعها عليه الصلاة والسلام في الاستفتاح تارةً يستفتح بما جاء في حديث عمر: سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك وتارةً بما جاء في حديث أبي هريرة: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد وهو في الصحيحين، وتارة يستفتح بما جاء في حديث عائشة: اللهم رب جبريل وميكائيل وإسرافيل فاطر السماء والأرض عالم الغيب والشهادة أنت تحكم بين عبادك فيما كانوا يختلفون، اهدني لما اختلف فيه من الحق، إنك تهدي من تشاء إلى صراط مستقيم.\nوهكذا في بعض الأحيان يستفتح بما في حديث علي: وجهت وجهي للذي فطر السموات والأرض حنيفًا وما أنا من المشركين.. إلى آخره، هو حديث طويل رواه مسلم في الصحيح، أو بما جاء في حديث ابن عباس في البخاري ورواه مسلم أيضًا وهو حديث طويل: اللهم لك الحمد أنت قيوم السموات والأرض ومن فيهن ولك الحمد أنت ملك السموات والأرض ومن فيهن ولك الحمد أنت نور السموات والأرض ومن فيهن... إلى آخر الحديث الطويل، فالمؤمن هكذا ..... والمؤمنة كذلك، يعني تارةً يستفتح بهذا وتارةً يستفتح بهذا، وإن استمر على واحد فلا بأس، وأصحها ما رواه أبو هريرة  عن النبي ﷺ أنه ..كان يستفتح إذا كبر في الصلاة للفريضة يقول: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد خرجه البخاري ومسلم في الصحيحين.\nأما الأذكار في الركوع والسجود فإنه يأتي منها بما تيسر، يشرع له أن يأتي بما تيسر، لكن يخص (سبحان ربي العظيم) في الركوع و (سبحان ربي الأعلى) في السجود، فيقول في الركوع: (سبحان ربي العظيم سبحان ربي العظيم) فإذا كررها ثلاثًا فهو أفضل والواجب مرة، وذهب الجمهور إلى أنها مستحبة فقط، ولكن ذهب جمع من أهل العلم إلى وجوب هذا الذكر: (سبحان ربي العظيم) في الركوع و (سبحان ربي الأعلى) في السجود؛ لأن الرسول حافظ عليها عليه الصلاة والسلام، وقال: صلوا كما رأيتموني أصلي وروي عنه عليه الصلاة والسلام أنه قال لما نزل قوله تعالى: فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ [الحاقة:52] قال: اجعلوها في ركوعكم، ولما نزل قوله تعالى: سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى [الأعلى:1] قال: اجعلوها في سجودكم.\nفينبغي للمؤمن والمؤمنة المحافظة على ذلك، (سبحان ربي العظيم) في الركوع و (سبحان ربي الأعلى) في السجود، والأفضل أن يكرر ذلك ثلاثًا وإن كرر أكثر فهو أفضل، ويستحب مع هذا أن يقول: (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي) في الركوع والسجود، تقول عائشة رضي الله عنها: كان النبي ﷺ يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي ويستحب أن يقول: (سبوح قدوس رب الملائكة والروح)، كان يقوله النبي أيضًا في الركوع والسجود عليه الصلاة والسلام، فإن أتى بما تيسر من هذا كان هذا أفضل، وإن اقتصر على البعض فلا بأس، وإن جمع الجميع فلا بأس، لكن لا يدع (سبحان ربي العظيم) في الركوع، ولا يدع (سبحان ربي الأعلى) في السجود ولو مرة، ويستحب له أن يكثر في السجود من الدعاء، يستحب له الإكثار من الدعاء في السجود؛ لقوله عليه الصلاة والسلام: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم ... فحري أن يستجاب لكم، رواه مسلم في صحيحه، وقال أيضا عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء رواه مسلم أيضًا.\nفالسنة الإكثار من الدعاء في السجود، مع قول: (سبحان ربي الأعلى، سبحان ربي الأعلى)، مع قول: (سبحانك اللهم ربنا وبحمدك اللهم اغفر لي)، وهكذا بين السجدتين يقول: (رب اغفر لي رب اغفر لي اللهم اغفر لي وارحمني واهدني وارزقني وعافني) يكرر ذلك، وإن دعا بزيادة (اللهم اغفر لي ولوالدي وللمسلمين) فلا بأس كله دعاء.\nوالسنة أن يطيل هذا الركن وهو الجلوس بين السجدتين كان النبي ﷺ يطيله حتى يقول القائل: قد نسي، وهكذا بعد الركوع السنة أن يطيل الاعتدال بعد الركوع، قال أنس : كان النبي ﷺ يطيل هذا الاعتدال بعد الركوع وبين السجدتين حتى يقول القائل: قد نسي بعض الناس ينقر هذا الركن ولا يعطيه حقه بل يعجل وهذا لا يجوز، بل الواجب الطمأنينة في جميع الصلاة، في الركوع والسجود والاعتدال بعد الركوع والجلوس بين السجدتين، يجب الاعتدال في هذا والطمأنينة.\nأما ذكر الاعتدال بعد الركوع فإنه لم يرد ما يدل على التكرار لكن يأتي به إذا تيسر كله: (ربنا ولك الحمد حمدًا كثيرًا طيبًا مباركًا فيه ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد)، هذا هو الكمال وإلا اقتصر على قوله: (ربنا ولك الحمد) أو (اللهم ربنا لك الحمد) أجزأه الإمام والمأموم والمنفرد، لكن إذا كمل كان أفضل، وإن اقتصر على قوله: (ربنا ولك الحمد ملء السموات وملء الأرض وملء ما بينهما وملء ما ما شئت من شيء بعد) فلا بأس أيضًا، ولكن الواجب: (ربنا ولك الحمد) أو (اللهم ربنا لك الحمد)، لأن الرسول عليه السلام قال: إذا قال الإمام: سمع الله لمن حمده، فقولوا: ربنا ولك الحمد فدل ذلك أن هذا هو الواجب والباقي مستحب وكمال.\nوهكذا الواجب بين السجدتين يقول: (رب اغفر لي)، فإن النبي ﷺ كان يحافظ على ذلك: (رب اغفر لي) والواجب مرة كالتسبيح في الركوع والسجود، ولكن إذا كرر ذلك ثلاثًا أو أكثر كان أفضل، (رب اغفر لي رب اغفر لي) لما يجلس بين السجدتين، وإذا زاد (اللهم اغفر لي وارحمني واهدني وارزقني وعافني واجبرني) كان أفضل. نعم.\nالمقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8421/حكم-الجمع-بين-اكثر-من-دعاء-وارد-في-الاستفتاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_336/33603.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":10383,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من اليمن -صنعاء- وباعثها المستمع صادق نعمان يسأل ويقول: إذا سجدت أيهما أضع أولًا: الكفين أم الركبتين؟","title":"ما السنة عند الهويِّ إلى السجود في الصلاة؟","answer":"الجواب: الأفضل الركبتان، تضع الركبتين ثم اليدين ثم الجبهة والأنف، هذا هو السنة، تبدأ بالركبتين؛ لأن الرسول ﷺ: نهى عن البروك كما يبرك البعير، البعير يبدأ بيديه، فأنت تبدأ بركبتيك لأنها برجليك، وفي الحديث الآخر: كان النبي ﷺ إذا سجد وضع ركبتيه قبل يديه وهو حديث حسن لا بأس به، يتفق مع أحاديث البروك.\nفالمقصود أن السنة والمشروع البداءة بالرجلين: الركبتين ثم يديك ثم جبهتك وأنفك، وعند الرفع ترفع رأسك ثم يديك ثم ركبتيك، هذا هو الأصح. نعم.","link":"https://binbaz.org.sa/fatwas/8555/ما-السنة-عند-الهوي-الى-السجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28008.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":10674,"question":"هل تغير موضع السجود في الصلاة يؤثر عليها؟","title":"حكم تغيير موضع السجود في الصلاة الواحدة","answer":"الجواب: لا نعلم في هذا شيئاً إذا سجد تقدم أو تأخر قليل عن موضع السجود لا يضر، المقصود أنه يتحرى السجود في المحل الذي لا يؤذيه، فإن كان فيه شيء أزاله مسحة واحدة بيده، المقصود أن كونه يتقدم قليلاً أو يتأخر قليلاً في السجود يتحرى ما يناسب جبهته وأنفه لا يضره، لكن يكون معتدل في السجود، بعض الناس ........... هذا غير مشروع، إنما يعتدل ويعتمد على كفيه، ويرفع ذراعيه، ويجافي عضديه عن جنبيه، وبطنه عن فخذيه، وفخذيه عن ساقيه، يكون معتدل في السجود، مستقيم في السجود، فإذا قدم جبهته قليلاً أو أخرها قليلاً تحرى المحل الذي يريحه هذا ما يضره. هذا نعم.","link":"https://binbaz.org.sa/fatwas/8873/حكم-تغيير-موضع-السجود-في-الصلاة-الواحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33023.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":11173,"question":"هذا السائل نبيل محمد حرفوش بالرياض يقول: لقد حدث في صلاة العصر ذات يوم أن الإمام في سجود الركعة الرابعة الأخيرة أتى بسجدة واحدة ولم ينتبه أحد على أساس بأنه أتى بالسجدتين، وبعد الانتهاء من الصلاة قال أحد المصلين للإمام: ناقص سجدة، فأتى الإمام بسجدتي السهو فقط، ولم يأت بالسجدة الناقصة، السؤال يا سماحة الشيخ: هل صلاة العصر هذه ما زالت معلقة لكونها ناقصة سجدة وهي ركن من أركان الصلاة، أو تعتبر صحيحة جزاكم الله خيرًا؟","title":"هل تجزئ سجدتا السهو عن ركن في الصلاة؟","answer":"الجواب:  إذا كان الإمام تذكر أنه ترك السجدة يلزمه الإعادة، وهكذا من معه يعيدون؛ لأن سجود السهو لا يكفي عن السجدة، والواجب عليه أن يأتي بالسجدة ثم يأتي بالتشهد ثم يسلم ثم يسجد للسهو، وإن سجد قبل السلام فلا بأس، يسجد سجود السهو. وبعض أهل العلم يرى أنه يقوم ويأتي بركعة كاملة. لكن الصواب أنه يأتي بالسجدة ويكفي، يعود يأتي بسجدة، يجلس يقول: رب اغفر لي رب اغفر لي ثم يسجد، ثم بعد السجود يقرأ التشهد ثم يسلم، ويسجد للسهو بعد ذلك، وإن سجد قبل السلام للسهو فلا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9346/هل-تجزى-سجدتا-السهو-عن-ركن-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29020.mp3","categories":["الركوع والسجود","سجود السهو"]},{"id":11866,"question":"في هيئة السجود هل النزول على اليدين، أم على الركبتين؟","title":"كيفية الهوي للسجود في الصلاة","answer":"الجواب:  السنة للقادر النزول على الركبتين، كما في حديث وائل وغيره، وهو المراد في حديث أبي هريرة: لا يبرك أحدكم كما يبرك البعير هذا الصواب؛ لأن بروك البعير يبرك على يديه، ونحن منهيون أن نبرك على أيدينا، نبرك على ركبنا التي في الرجلين، هذا هو السنة، وهذا هو الصحيح، وهو قول الجمهور من أهل العلم، أن السنة البروك على ركبتيه، لا على يديه؛ خلافًا للبعير، هذا إذا كان قادرًا، أما إذا كان عاجزًا لكبر السن، أو لمرض؛ فإنه يبرك على يديه، لا بأس لأجل العجز. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10050/كيفية-الهوي-للسجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39713.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":12121,"question":"هل يجوز الدعاء من القرآن الكريم في سجود الصلاة فرضًا كان، أم نافلة؟","title":"حكم الدعاء من القرآن في السجود","answer":"الجواب: نعم. يجوز الدعاء بدعوات القرآن إذا كان ذلك على سبيل الدعاء، لا على سبيل القراءة، فقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه نهى عن القراءة في الركوع والسجود، لكن إذا دعا مثل: رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8]، أو قال: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201]، هذا لا بأس على سبيل الدعاء، لا على سبيل القراءة، فدعوات القرآن إذا قيلت في السجود أو في آخر التحيات على سبيل الدعاء والضراعة إلى الله لا على سبيل القراءة لا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10306/حكم-الدعاء-من-القران-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43806.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":12188,"question":"أيضًا من الأشياء التي يلاحظها على بعض المصلين أمور ذكر منها مثلًا: مجافاة المرفقين بشدة، الامتداد الفاحش حال السجود، الجلسة الخفيفة قبل القيام للركعة الثانية، وهل هي لازمة؟ أيضًا يلاحظ أن هناك من يبالغ في الالتفات إلى الوراء عند التسليم، والتورك للمأموم في الصف المزدحم، والتماوت -كما يقول- في الصلاة، ووضع الكف على الكف، لا على الرسغ في القيام، يرجو التوجيه حول هذه الأمور سماحة الشيخ.","title":"حكم التجافي للمأموم والتماوت في الصلاة والمبالغة في الالتفات","answer":"السنة للمؤمن أن يلاحظ عدم الأذى، فلا يؤذ جيرانه بمرافقه، بل يتضام حتى لا يؤذي أحدًا، وإن كان مشروعًا له المجافاة بين عضديه وجنبيه، لكن لا يضايق إخوانه إذا كان الصف فيه ضيق حال السجود؛ فيفرج حسب الطاقة من غير أذى، كل واحد يلاحظ عدم الأذى، يفرج مهما أمكن من غير حاجة للإيذاء، وإذا لم يستطع فلا يؤذ جيرانه، ولو ضم عضديه إلى جنبيه إذا لم يستطع؛ فإنه لا يؤذيهم، ولا يشق عليهم، بل يرفق بهم، فالمؤمن أخو المؤمن، والله يقول : وَالَّذِينَ يُؤْذُونَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ بِغَيْرِ مَا اكْتَسَبُوا فَقَدِ احْتَمَلُوا بُهْتَانًا وَإِثْمًا مُبِينًا [الأحزاب:58].  فالمسلم لا يؤذي أخاه، ولا يضره، وهكذا الامتداد حال السجود غير مشروع، السنة أن يعتدل في السجود، ويجافي عضديه عن جنبيه، وبطنه عن فخذيه، وفخذيه عن ساقيه، ويكون معتدلًا، ويرفع ذراعيه من الأرض، ويعتمد على كفيه في السجود، ويكون معتدلًا اعتدالًا كاملًا، لا شبه منبطح، يمد نفسه كالمنبطح، بل يعتدل، ويقيم ظهره وبدنه إقامة تامة؛ حتى يكون معتمدًا على كفيه، رافعًا بطنه عن فخذيه، وفخذيه عن ساقيه حال السجود.  هكذا ينبغي للمؤمن، ولا يكون متماوتًا في الصلاة، بل يكون عنده العناية التامة بالصلاة، والخضوع فيها، والإقبال على الله  حتى تكون صلاته صلاة خشوع، وإقبال على الله، وطمأنينة، كفعل النبي ﷺ وأصحابه .  وكذلك لا يبالغ المبالغة الزائدة، السنة كان النبي إذا التفت في السلام يلتفت حتى يرى بياض خده -عليه الصلاة والسلام- يمينًا وشمالًا، فلا يلتفت أكثر من هذا، يلتفت هكذا وهكذا؛ حتى يُرَى خده لا بأس، يراه من ورائه، لا حرج، كما فعله النبي ﷺ فالإمام يلتفت للمأمومين، والمأموم يلتفت عن يمينه وعن شماله إلى مَنْ عن يمينه وعن شماله؛ حتى يرى مَنْ يمينه ومَنْ شماله خده إذا التفت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10374/حكم-التجافي-للماموم-والتماوت-في-الصلاة-والمبالغة-في-الالتفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44315.mp3","categories":["الركوع والسجود"]},{"id":12668,"question":"له سؤال آخر يقول فيه: ما مقادير الأقوال والأفعال الواجبة والمستحبة في الصلاة؟","title":"مقدار ما يجب في الركوع والسجود من الأذكار","answer":"الجواب:  الواجب في السجود: سبحان ربي الأعلى مرة، وفي الركوع: سبحان ربي العظيم مرة، والزائد مستحب، يكرر ويأتي بقول: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، هذا مستحب. وهكذا قوله: سبوح قدوس رب الملائكة والروح في الركوع والسجود، هذا مستحب، كذلك الدعاء في السجود مستحب، وهكذا بين السجدتين يقول: رب اغفر لي، الواجب مرة، وإذا كرر كان أفضل، وإذا زاد: \"اللهم اغفر لي وارحمني واهدني واجبرني وارزقني وعافني\" كان أفضل مع الطمأنينة في الجميع، وعدم العجلة، وهكذا إذا رفع من الركوع إن كان إمامًا، أو منفردًا، يقول: \"سمع الله لمن حمده، ربنا ولك الحمد\" أو \"اللهم ربنا ولك الحمد\" أو \"ربنا لك الحمد\" كله جاء، هذا الواجب. وإن كان مأمومًا إذا رفع يقول: \"ربنا ولك الحمد\" أو \"ربنا لك الحمد\" أو \"اللهم ربنا لك الحمد\" أو \"اللهم ربنا ولك الحمد\" كله حق، هذا الواجب والزائد مستحب (حمدًا كثيرًا ... ) إلى آخره مستحب، وهو الأفضل أن يكمل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10878/مقدار-ما-يجب-في-الركوع-والسجود-من-الاذكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_416/41602.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":12843,"question":"يسأل عن مشروعية الدعاء أثناء السجود، هل هو جائز؟","title":"حكم الدعاء أثناء السجود","answer":"الجواب:  سنة الدعاء في السجود، سنة، الدعاء في السجود أمر به النبي ﷺ في صحيح مسلم عن أبي هريرة  عن النبي ﷺ أنه قال: أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء وهذا حديث صحيح، يدل على شرعية الدعاء في السجود، ولهذا قال ﷺ: أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء وفي حديث ابن عباس عند مسلم -رحمه الله- في الصحيح يقول ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، فهذان الحديثان الصحيحان يدلان على شرعية الدعاء في السجود. وثبت عنه ﷺ: أنه كان يدعو في سجوده ويقول: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره فقد ثبت هذا من فعله، ومن قوله، عليه الصلاة والسلام. فيشرع للمؤمن أن يدعو في السجود في الفرض والنفل جميعًا؛ لأن الرسول أمر بهذا، وفعله -عليه الصلاة والسلام-نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11057/حكم-الدعاء-اثناء-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46409.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":12950,"question":"تقول السائلة: سمعت من بعض الناس بأنه لا يجوز السجود على القماش الأسود، هل هذا صحيح؟","title":"حكم السجود على القماش الأسود","answer":"الجواب:  ليس بصحيح، يجوز السجود على القماش الأسود والأحمر والأصفر، لكن يكون ما فيه نقوش، الأحسن ألا يكون فيه نقوش تشغل المصلي، إذا كان فيه نقوش؛ تركه أولى، سواء أصفر وإلا أحمر وإلا أسود وإلا غيره، أما إذا كان سادة؛ فهو الأفضل، سواء كان أسود أو أحمر أو أخضر أو غير ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/11166/حكم-السجود-على-القماش-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50209.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13197,"question":"يقول السائل في آخر أسئلته: ما حكم وضع اليدين بعد الرفع من الركوع مثل: السدل، أم القبض، وجهونا جزاكم الله خيرًا؟","title":"أفضلية الضم بعد الرفع من الركوع","answer":"الجواب:  الأفضل القبض بعد الرفع من الركوع، الأفضل القبض؛ لأنه ثبت عن النبي ﷺ ما يدل على ذلك من حديث وائل بن حجر، ومن حديث قبيصة بن هلب الطائي عن أبيه \"أن النبي ﷺ كان يضع يديه على صدره حال قيامه في الصلاة\" وهذا القيام يشمل ما بعد الركوع، وما قبل الركوع؛ لأنه قيام، فيضع يديه على صدره، هذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11466/افضلية-الضم-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51204.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13228,"question":"نختم هذا اللقاء بسؤال السائل محمد علي يقول: هل يجب على المصلي أن يكشف عن جبينه عند السجود في الصلاة، مثلًا: الطاقية، أو الغترة، أو العمامة، أو يلزمه ذلك؟","title":"هل يجب على المصلي أن يكشف جبينه عند السجود؟","answer":"الجواب:  أفضل وإلا لا يلزمه، لو سجد على الطاقية، أو على العمامة، أو على غيرهما لا بأس، ولكن كونه يحسرها حتى تباشر جبهته المصلى يكون هذا أفضل وأولى، أن يباشر بجبهته وأنفه المصلى، نعم.","link":"https://binbaz.org.sa/fatwas/11508/هل-يجب-على-المصلي-ان-يكشف-جبينه-عند-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51221.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13805,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ح. م. م) الشائع أخونا سؤاله مطول بعض الشيء ملخصه: أنه لاحظ أن كثيرًا من الناس لا يسجدون على الأعضاء السبعة كاملة ويرجو من سماحة الشيخ تنبيههم جزاكم الله خيرا.","title":"حكم ترك السجود على أحد الأعضاء السبعة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالواجب على كل مسلم ومسلمة السجود على الأعضاء السبعة؛ وهي الوجه والجبهة والأنف والكفان والركبتان وأطراف القدمين، لما ثبت عن النبي ﷺ أنه قال: أمرت أن أسجد على سبعة أعظم على الجبهة -وأشار بيده إلى أنفه- والكفين والركبتين وأطراف القدمين. فالواجب على جميع المسلمين من الذكور والإناث أن يعنوا بهذا وأن يحرصوا على ذلك، وهذا السجود على هذه الأعضاء فرض ركن لابد منه، فلا يجوز التساهل في ذلك، بل يجب على المصلي ذكرًا كان أو أنثى أن يسجد على هذه السبعة في الفرض والنفل جميعًا، وإذا تركها عمدًا بطلت صلاته، وإن تركها سهوًا فإن أمكنه أن يأتي بها في الحال أتى بها في الحال، وإن لم يذكرها إلا بعدما قام إلى الركعة الأخرى أتى بركعة بدالها بعد ذلك إذا كمل يأتي بركعة بدل ما ترك من الأعضاء، وتقوم الركعة الثانية مقام الأولى مقام التي قبلها التي ترك منها العضو أو العضوين.\nوالحاصل أنه لابد من السجود على هذه الأعضاء السبعة ولا يجوز تركها ولا ترك شيء منها لا في الفرض ولا في النفل. نعم.\nويسجد للسهو أيضًا إذا كان تركها سهوًا بأن يرفع يده ولا سجد عليها، أو إحدى رجليه لم يسجد عليها ساهيًا ثم تذكر بعد ذلك بعدما اشتغل بالركعة التي بعدها فإنه يأتي بركعة بدلاً منها ويسجد للسهو سجدتين قبل أن يسلم ثم يسلم. نعم.\nالجواب: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12171/حكم-ترك-السجود-على-احد-الاعضاء-السبعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60201.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13831,"question":"يقول: كيف تكون وضع الرجلين عند السجود؟ هل هي مضمومة؟ أم متفرقة؟","title":"كيفية وضع الرجلين عند السجود في الصلاة","answer":"الجواب: مفرقة، السنة أن يفرقهما كما يفرق يديه إذا سجد، وهكذا يفرق رجليه إذا سجد، أما ما يروى: أنه ﷺ كان ساجدًا وكعبه ملتصق بالكعب الآخر فهذا فيه نظر، والظاهر أنه شاذ مخالف للأحاديث الصحيحة رواه الحاكم وجماعة، والمحفوظ: أنه ﷺ كان يقيم قدميه كل واحدة منفردة عن الأخرى. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12201/كيفية-وضع-الرجلين-عند-السجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53711.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13834,"question":"يقول: كيف تكون وضع الرجلين عند السجود؟ هل هي مضمومة؟ أم متفرقة؟","title":"كيفية وضع الرجلين عند السجود في الصلاة","answer":"الجواب: مفرقة، السنة أن يفرقهما كما يفرق يديه إذا سجد، وهكذا يفرق رجليه إذا سجد، أما ما يروى: أنه ﷺ كان ساجدًا وكعبه ملتصق بالكعب الآخر فهذا فيه نظر، والظاهر أنه شاذ مخالف للأحاديث الصحيحة رواه الحاكم وجماعة، والمحفوظ: أنه ﷺ كان يقيم قدميه كل واحدة منفردة عن الأخرى. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12201/كيفية-وضع-الرجلين-عند-السجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53711.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":13894,"question":"سماحة الشيخ! في سؤاله الثاني يقول: هل الصحيح أن ينزل المصلي بيديه قبل ركبتيه، أم أن الأصح ما نراه من نزول المصلين بركبتيهم إلى السجود؟","title":"حكم البدء بالركبتين قبل اليدين عند السجود","answer":"الجواب: هذا هو السنة، كان النبي ﷺ يهوي إلى سجوده على ركبتيه، ويقول: لا يبرك أحدكم كما يبرك البعير، والبعير يبرك على يديه يقدم يديه، فالسنة لمن عنده قوة أن ينزل على ركبتيه، وتكون يداه بعد ذلك، ثم وجهه، هذا السنة، الركبتان ثم اليدان ثم الوجه، هذا إذا كان يقوى على ذلك، وهذا هو الأفضل، فإن أصابه ما يمنعه من ذلك من كبر سن أو مرض سجد على يديه والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12265/حكم-البدء-بالركبتين-قبل-اليدين-عند-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53807.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":14175,"question":"يقول يا سماحة الشيخ هذا السائل في هذا  أقول في سجودي أحيانًا الصلاة الإبراهيمية المعروفة بالكامل في صلاة النفل، فهل يجوز ذلك مع الدعاء، اللهم آت محمد..","title":"حكم قول الصلاة الإبراهيمية و(اللهم آت محمدًا الوسيلة...) في السجود","answer":"الجواب: هذا من أسباب الإجابة، يحمد الله ويثني عليه ويصلي على النبي ﷺ ولو في السجود ولو في آخر الصلاة، يثني على الله ويصلي على النبي ﷺ ثم يدعو؛ لأن هذا من أسباب الإجابة، كما أنه في التحيات يقرأ التحيات ثم يصلي على النبي ﷺ ثم يدعو؛ لأن التحيات ثناء على الله، ثم بعدها الصلاة على النبي ﷺ ثم يدعو، فإذا أحب يدعو في السجود ثم يتهجد بالليل، يحمد الله ويثني عليه ويصلي على النبي ﷺ ويدعو؛ لأن هذا من أسباب الإجابة.\nالمقدم: يقول يا سماحة الشيخ عبد العزيز: هل يجوز أن أضيف هذا الدعاء : اللهم آت محمدًا الوسيلة والفضيلة والدرجة العالية الرفيعة وذلك في الصلاة الإبراهيمية؟\nالشيخ: لا، المشروع الصلاة الإبراهيمية التي بينها لأصحابه لما سألوه: «كيف نصلي عليك؟ قال: قولوا: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد وجاءت بألفاظ أخرى وكل ما صح عن النبي ﷺ في هذا يفعل، بعد قراءة التحيات بعد الشهادتين، أما اللهم آت محمداً الوسيلة هذه بعد الأذان هذه تقال بعد الأذان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12618/حكم-قول-الصلاة-الابراهيمية-واللهم-ات-محمدا-الوسيلة-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54710.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":14368,"question":"يقول السائل: هل هناك علامة تظهر في جبهة الفرد تسمى علامة الصلاة؟","title":"هل في الجبهة علامة تسمى علامة الصلاة؟","answer":"الجواب: قد تقع لبعض الناس، قد يبين على جبهته بعض الشيء؛ لكثرة سجوده، قد يقع هذا، نعم.","link":"https://binbaz.org.sa/fatwas/12849/هل-في-الجبهة-علامة-تسمى-علامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55110.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":14842,"question":"من الأوصاف التي وصف بها المنافقون أنهم إذا سجدوا نقروا، وإذا ركعوا ربضوا، فكيف يكون الربوض لتحاشي ذلك ومخالفتهم؟","title":"معنى الربض في السجود","answer":"الجواب: المعروف عن المنافقين النقر، الذي ينقرها يعني: يعجل فيها في ركوعه وسجوده، لا يذكر الله فيها إلا قليلًا.  أما الربض في كلام بعض العلماء فالربض كونه يسجد سجود ما هو معتدل، مثل ربض البهيمة، يسجد سجود ما هو معتدل.  فالسنة أن يعتدل في سجوده، يسجد على يديه وركبتيه، وأطراف قدميه وجبهته وأنفه رافعًا بطنه عن فخذيه وفخذيه عن ساقيه، ورافعًا ذراعيه عن الأرض، هذا هو السجود المعتدل، ما يربض ضامًا بعضه إلى بعض؛ بطنه على فخذيه وفخذيه على ساقيه وذراعيه على الأرض مثل ربض البهيمة، هذا مكروه لا ينبغي، لكن السنة أن يسجد سجودًا معتدلًا، ليس برابض، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13356/معنى-الربض-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64412.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":14848,"question":"هذه رسالة وصلت إلى البرنامج من بغداد، باعثها المستمع شاكر أبو محمود، يقول فيها: في الصلاة وأثناء السجود مما يدعو إلى إطالة السجود نقوم بعض الأحيان برفع الرأس، أو تحريكه يمينًا وشمالًا عن موضع السجود للاستراحة، أو نحو ذلك من الأسباب، فهل يعتبر ذلك نهاية لتلك السجدة، ولا يجوز بعدها الاستمرار بالسجود أم كيف توجهون الناس؟","title":"حكم رفع الرأس وتحريكه يمينًا وشمالًا في السجود","answer":"الجواب: هذا العمل مكروه، ولا ينبغي؛ لأن هذا عبث، ولكن يسجد طاقته، ولا يطول تطويلًا يلجئه إلى هذا العمل، يسجد يأتي بالتسبيح ثلاث مرات، أو خمس مرات، ويدعو بما تيسر، ثم يرفع، لا يكلف نفسه، وإذا كان إمامًا كذلك لا يشق على الناس، أما أنه يرفع رأسه ويومي به هذا لا، مكروه، وهو من العبث الذي لا ينبغي، وإذا كثر قد يبطل الصلاة إذا كثر وتوالى، لكن بكل حال هو مكروه، ولا ينبغي، والسجود باقي إذا رفع رأسه قليل، ثم وضعه، فهذا من كمال السجود ما يبطل السجود، لكن لا ينبغي هذا العمل، بل يسجد ما يسر الله له، ثم يرفع رفعًا تامًا، ويأتي بالسجدة الثانية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13353/حكم-رفع-الراس-وتحريكه-يمينا-وشمالا-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64409.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":14895,"question":"سؤال طويل لأخينا كالتالي: يقول الرسول ﷺ في حديث له: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم وفي صلاة للرسول ﷺ قال رجل -عند الرفع من الركوع بعد قوله: ربنا ولك الحمد- \"حمدًا كثيرًا طيبًا مباركًا فيه\" وعندما انتهى الرسول ﷺ من الصلاة سأل عن القائل لهذا الكلام، فقال الرجل: أنا يا رسول الله، فقال ﷺ: لقد رأيت بضعًا وثلاثين ملكًا يبتدرونها، أيهم يكتبها أول فأقر رسول الله ﷺ ما قاله الرجل،  هل يفهم مما تقدم أن يقول الواحد في صلاته في الركوع مما يرى فيه تعظيمًا للرب كقوله: سبحانك يا مالك زمام الخلق، وبيده كل شيء، أحمدك حمدًا كثيرًا، مما فيه تعظيم للرب؟ أو أن يقول في السجود بأي دعاء من أمر الدنيا والآخرة، وأقصد بذلك عدم الاقتصار على أذكار الركوع والسجود الواردة عن رسول الله ﷺ؛ وذلك لأن الصحابة كانوا يأتون بدعاء فيقره رسول الله ﷺ؟","title":"حكم تعظيم الرب في الركوع بما لم يرد في السنة","answer":"الجواب: الحديث المذكور في النهي عن القراءة راكعًا وساجدًا ثابت، رواه مسلم في الصحيح عن ابن عباس -رضي الله تعالى عنهما-، عن النبي ﷺ أنه قال: إني نهيتُ أن أقرأ القرآن راكعًا أو ساجدًا، فأما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم المعنى: حري أن يستجاب لكم، وقد روي معنى شطره الأول عن علي ، أنه ثبت عن علي أيضًا  في النهي عن القراءة راكعًا أو ساجدًا، فلا يجوز للمسلم أن يقرأ في الركوع والسجود، لكن لو دعا في السجود بدعاء يوافق ما في القرآن لم يكن قارئًا، إذا أراد الدعاء فقط، كأن يقول: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] ، رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8] لا يقصد القراءة يقصد الدعاء فلا حرج في ذلك، وكذلك إذا عظم الرب بأنواع من التعظيم لم ترد لا بأس؛ لأن الرسول ﷺ قال: عظموا فيه الرب فعمم، فإذا قال من التعظيم ما قاله السائل، أو اقتصر على الوارد كله طيب، وكونه يقتصر على الوارد، ويكثر من الوارد، ويكرر أفضل؛ ولهذا قال ﷺ لما سمع الرجل قال: حمدًا كثيرًا طيبًا، قال: لقد رأيت -كذا مثلما في السؤال- بضعًا وثلاثين ملكًا يبتدرونها، أيهم يكتبها فأقرها. فدل ذلك على استحباب مثل هذا التحميد، أن يقول: ربنا ولك الحمد حمدًا كثيرًا طيبًا مباركًا فيه ملء السماوات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد؛ لأن الرسول ﷺ فعل بعض هذا، وأقر هذه الزيادة \"حمدًا كثيرًا\" وكان يقول ﷺ: ربنا ولك الحمد وربما قال: اللهم ربنا لك الحمد، ملء السماوات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد فلما أقر الرجل على قوله: \"حمدًا كثيرًا\" إلى آخره دل على شرعية ذلك، وأن يقول: ربنا ولك الحمد، أو اللهم ربنا لك الحمد حمدًا كثيرًا طيبًا مباركًا فيه، ملء السماوات، وملء الأرض، وملء ما بينهما وملء ما شئت من شيء بعد؛ لأن هذا كله ثناء. وكان ﷺ ربما زاد: أهل الثناء والمجد، أحق ما قال العبد، وكلنا لك عبد، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد في وقوفه بعد الركوع، في اعتداله بعد الركوع، كل هذا مشروع، أقله اللهم ربنا لك الحمد، أو ربنا ولك الحمد، هذا الواجب عند جمع من أهل العلم، وأكثر أهل العلم على أنه سنة، لكن القول بوجوب هذا المقدار هو الأصح؛ لأن الرسول أمر به -عليه الصلاة والسلام-، وما زاد على ذلك فهو كله سنة. قوله: حمدًا كثيرًا طيبًا مباركًا فيه وقوله: ملء السماوات وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد كل هذا سنة، كذلك قوله: أهل الثناء والمجد، أحق ما قال العبد، وكلنا لك عبد، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد يعني: ولا ينفع ذا الغنى والحظ والبخت منك غناه، فالمعنى: كلنا فقراء إلى الله ، فإذا أتى بهذا تارة وحذفه تارة فلا بأس لأنه سنة. والدعاء كذلك يدعو بما يسر الله من الدعاء، ولكن تحري الدعاء الوارد أفضل، كما أنه يتحرى التعظيم الوارد في الركوع والسجود سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي هذا مما ورد في الركوع والسجود سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، سبوح قدوس، رب الملائكة والروح، سبحان ربي العظيم، سبحان ربي العظيم، سبحان ربي العظيم ولو قال: سبحان الملك العظيم، أو سبحان الله العظيم كله تعظيم كله تعظيم. لكن كونه يتحرى الأذكار الواردة في الركوع والدعوات الواردة في السجود كله طيب أفضل من غيره، ولكن إذا دعت الحاجة إلى أن يدعو بدعوات أخرى فيدعو؛ لقوله ﷺ: وأما السجود فاجتهدوا في الدعاء وللحديث الثاني رواه مسلم في الصحيح عن النبي ﷺ أنه قال: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء رواه مسلم. فهذا يدل على أنه يشرع إكثار الدعاء في السجود بما يحتاجه المسلم، فإذا كان محتاجًا للزواج قال: اللهم يسر لي زوجة صالحة، أو للذرية اللهم يسر لي ذرية طيبة، أو لكسب حلال، قال: اللهم يسر لي كسبًا حلالًا كل هذا لا بأس به؛ لأن الحاجة تدعو إلى ذلك، وإذا أكثر من الدعوات المشروعة الواردة كان أفضل، مثل: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره؛ لأن هذا ورد عن النبي ﷺ. كذلك: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم هذا دعاء وارد عن النبي ﷺ، أو اللهم اغفر لي ما قدمت وما أخرت، وما أسررت وما أعلنت، وما أسرفت وما أنت أعلم به مني، أنت المقدم وأنت المؤخر، لا إله إلا أنت هذا من الدعاء الوارد، ولكن يشرع مع هذا أن يقول: سبوح قدوس، رب الملائكة والروح يقوله في السجود كما يقوله في الركوع أيضًا، ويقول: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي في الركوع والسجود، هذا تعظيم معه دعاء، قالت عائشة -رضي الله عنها-: كان النبي ﷺ يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13396/حكم-تعظيم-الرب-في-الركوع-بما-لم-يرد-في-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49203.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":15239,"question":"هذه رسالة وردتنا من أحد السادة المستمعين، يقول في رسالته: السؤال الأول: كنت أصلي وما زلت والحمد لله، ولكن بداية صلاتي كنت أصلي نصف صلاة، أي: مثل صلاة الفجر سجدتين، أتصور أني أصلي صلاة كاملة، وكذلك صلاة الظهر أربع ركعات، كنت أصليها أربع سجدات، وكذلك الفرض...الشيخ: أعد، أعد.المقدم: يقول: كنت أصلي وما زلت والحمد لله، ولكن بداية صلاتي كنت أصلي نصف صلاة، أي: مثل صلاة الفجر سجدتين أتصور أني أصلي صلاة كاملة، وكذلك صلاة الظهر أربع ركعات كنت أصليها أربع سجدات، وكذلك الفرض لصلوات أخرى، ويقول: استمريت على هذا المنهج حوالي أربع سنوات، والأمر الذي جعلني أستمر على هذا الخطأ هو الحياء، أستحي أن أسأل أحدًا حتى والدي الذي هو معي في البيت، وإني مقتنع إذا سألته سوف يجيبني بالحقيقة، لكن لم أسأله، وبعد هذه الفترة الطويلة -أي: أربع سنوات- أو أقل أو أكثر، فإني سألت أحد الأشخاص، وقال لي: إن صلاتك نصف الفرض. سؤالي: هل علي قضاء؟ وكيف أصليها قضاء؟الله يوفقكم ويوفقنا لما فيه الخير.","title":"حكم من يسجد سجدة واحدة في كل ركعة جهلًا","answer":"الجواب: هذه المسألة غريبة جدًا، رجل بين المسلمين تخفى عليه صفة الصلاة، ويصلي في كل ركعة سجدة واحدة، لا حول ولا قوة إلا بالله، لا ريب أن هذا من ثمرات التخلف عن الصلاة في الجماعة، لو كان السائل يصلي في الجماعة لعرف كيف يصلي، ولرأى الناس يصلون سجدتين في كل ركعة، ولكن بسبب صلاته في البيت، وعدم السؤال وقع في هذا الغلط الكبير. والعلم يطلب، ويسأل عنه، ولا يستحيا في طلبه، يقول الله -جل وعلا-: إِنَّ اللَّهَ لا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً فَمَا فَوْقَهَا[البقرة:26] ويقول سبحانه في آية الأحزاب: وَاللَّهُ لا يَسْتَحْيِي مِنَ الْحَقِّ[الأحزاب:53] فهو  لا يستحي أن يقول الحق، وأن يأمر بالحق -جل وعلا-، وتقول أم سليم لما سألت النبي ﷺ: «يا رسول الله! إن الله لا يستحي من الحق، هل على المرأة من غسل إذا هي احتلمت؟ فقال النبي ﷺ: نعم، إذا هي رأت الماء. فالحق ليس فيه حياء، أن يسأل عنه، ويتفقه فيه المسلم والمسلمة، وقال مجاهد بن جبر التابعي الجليل -رحمه الله-: \"لا يتعلم العلم مستح ولا مستكبر\" فالمستحي لا يتعلم، والمتكبر لا يتعلم، فلا يليق بالمؤمن أن يستحي في العلم، وهذا ليس بحياء في الحقيقة، ولكنه ضعف وخور وتهاون وتكاسل، وإلا فالحياء الصحيح الحياء المشروع يدعو إلى الخير، ولا يمنع من الخير، مثلما قال النبي ﷺ: الحياء خير كله، الحياء لا يأتي إلا بخير، الحياء من الإيمان. فالحياء كله خير، وهو خلق كريم، يدعو إلى مكارم الأخلاق، ومحاسن الأعمال، وينهى عن سفاسف الأخلاق، وسيىء الأعمال. والذي يظهر من الشريعة أنك -أيها السائل- ليس عليك القضاء؛ لأنك في حكم المتعمد لعدم سؤالك مع تيسر السؤال، وعلى فرض أنك جاهل، وأنك تظن أن هذا هو الصواب، فإن المدة قد طالت، والجهل بهذا عظيم، فعليك التوبة والإنابة إلى الله والاستغفار، وعدم العود إلى مثل هذا العمل، وعليك أن تسأل أهل العلم عن كل شيء، وأن تصلي مستقبلًا كما يصلي المسلمون، كل ركعة فيها ركوع وفيها سجدتان، كل ركعة في الفريضة والنافلة فيها ركوع في الهواء، وفيها سجدتان في الأرض، لا بد من هذا. فعليك أن تستقبل حياتك بهذه الصلاة؛ كل ركعة فيها ركوع وسجدتان، وعليك أن تصلي مع المسلمين في المساجد، ولا تصلي في البيت، الصلاة في المساجد مع المسلمين أمر لازم، وأمر مفترض، كما في الحديث عنه -عليه الصلاة والسلام- أنه قال: من سمع النداء فلم يأت فلا صلاة له إلا من عذر وسأله -عليه الصلاة والسلام- رجل أعمى، فقال: «يا رسول الله، ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب فأمره أن يجيب النداء، ولم يرخص له مع أنه أعمى بعيد الدار، ليس له قائد يلائمه، ومع هذا أمره أن يصلي في المسجد، ولم يرخص له في أن يصلي في بيته، فكيف بحال البصير والصحيح؟ حاله أقل عذرًا من ذلك، بل لا عذر له ما دام صحيحًا يسمع النداء بصيرًا، فهو أعظم من ذاك الذي ليس له قائد وهو أعمى، فالواجب عليه أعظم، فإذا كان الأعمى لا يعذر، فالذي هو بصير قوي قادر لا يعذر من باب أولى. والنبي ﷺ لما سأله الأعرابي الذي دخل المسجد فنقر الصلاة، قال له النبي ﷺ: ارجع فصل فإنك لم تصل صلاها ثلاث مرات، ثم قال: يا رسول الله، والذي بعثك بالحق لا أحسن غير هذا فعلمني، فقال له النبي ﷺ: إذا قمت إلى الصلاة فأسبغ الوضوء، ثم استقبل القبلة، فكبر، ثم اقرأ ما تيسر معك من القرآن، ثم اركع حتى تطمئن راكعًا، ثم ارفع حتى تعتدل قائمًا، ثم اسجد حتى تطمئن ساجدًا، ثم ارفع حتى تطمئن جالسًا، ثم اسجد حتى تطمئن ساجدًا، ثم افعل ذلك في صلاتك كلها هكذا أمره -عليه الصلاة والسلام- بأن يصلي، هكذا بالطمأنينة والاعتدال والخشوع، وعدم العجلة، ولم يأمره بقضاء الماضي، ما أمره بقضاء الصلوات الماضية التي لم يكملها، بل نقرها لجهله، وقلة بصيرته فلهذا أمره أن يستقبل أمره ويصلي صلاة مستقيمة يطمئن فيها لربه ويخشع، ولم يأمره بقضاء الماضي. فهكذا أنت؛ لأنك تركت الصلاة في الحقيقة عن جهل، وقلة بصيرة، وتفريط، فعليك التوبة إلى الله، والإنابة إليه، ولا يلزمك القضاء للمدة الماضية فيما يظهر من قواعد الشرع، ومن هذا الحديث الشريف، والله يتوب عليك، وعليك بالإكثار من الأعمال الصالحات والاستغفار، والاستكثار من ذكر الله  فإن الحسنات يذهبن السيئات، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13740/حكم-من-يسجد-سجدة-واحدة-في-كل-ركعة-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_669/nour_66902.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":15339,"question":"ماذا يجب على المأمومين إذا قال الإمام: الله أكبر، وسمع الله لمن حمده، هل يردوا بصوت ظاهر أم بسر، سواء أكانت الصلاة سرية أو جهرية؟ وهذا السائل من اليمن.","title":"كيف يكون تكبير المأموم ودعاؤه خلف الإمام؟","answer":"الجواب: إذا قال الإمام: سمع الله لمن حمده،.يقول المأموم: ربنا ولك الحمد، ولا حاجة إلى الجهر، يقول كلامًا يسمع نفسه، ربنا ولك الحمد؛ لقوله ﷺ: إذا قال الإمام: سمع الله لمن حمده، فقولوا: ربنا ولك الحمد هكذا أمر ﷺ، الإمام يقول: سمع الله لمن حمده، ربنا ولك الحمد.  أما المأموم فيقول عند الرفع: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، أو ربنا لك الحمد، كله واسع، الحمد لله، نعم. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/13842/كيف-يكون-تكبير-الماموم-ودعاوه-خلف-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56616.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":15412,"question":"سؤالها الأخير تقول: ما حكم وضع المرفقين على الأرض أثناء السجود؟","title":"حكم وضع المرفقين على الأرض أثناء السجود","answer":"الجواب: هذا مكروه، ولا ينبغي، النبي ﷺ قال: إذا سجدت فضع كفيك وارفع مرفقيك و\"نهى عن افتراش كافتراش السبع\" فالسنة أن يرفع مرفقيه، سواء رجل أو امرأة، يرفع ذراعيه عن الأرض، ويعتمد على كفيه حال السجود، هذه هي السنة.","link":"https://binbaz.org.sa/fatwas/13920/حكم-وضع-المرفقين-على-الارض-اثناء-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68412.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":15898,"question":"رسالة وصلت إلى البرنامج من المستمع (ج. ع) من محافظة الرقة يسأل ويقول: في صلاة السنة بعد الركعة الأولى إنني سجدت وسهوت عن الركوع فما الحكم؟جزاكم الله خيرًا.","title":"حكم من نسي الركوع في النافلة","answer":"الجواب: عليك أن ترجع وتقف ثم تركع ثم ترفع ثم تسجد ثم تسجد للسهو سجدتين قبل أن تسلم، كالفريضة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14491/حكم-من-نسي-الركوع-في-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74518.mp3","categories":["الركوع والسجود","سجود السهو"]},{"id":15995,"question":"السائل يقول في هذا السؤال -سماحة الشيخ-: في الصلاة البعض من الناس يضعون الأيدي في السجود، والبعض تسبق الركبة أو الركبتين قبل اليدين، ما هي الطريقة الصحيحة للسجود؟","title":"ما السنة عند الهوي للسجود؟","answer":"الجواب: إذا كان قادرًا فالأفضل أن يقدم ركبتيه، ثم يديه، ثم جبهته، وأنفه هذا السنة، وعند الرفع يرفع رأسه ثم يديه، ثم ركبتيه، هذا إذا كان قادرًا، أما إذا كان عاجزًا فلا بأس أن يقدم يديه، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/14598/ما-السنة-عند-الهوي-للسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57818.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16105,"question":"أم محمد من منطقة جيزان محافظة صبيا أرسلت بسؤالين، سؤالها الأول تقول: صليت صلاة العصر، وعند سجودي لا أدري هل سجدت سجدة، أم سجدتين، وأكملت بسجود السهو، دون أن أسجد سجدة أخرى رغم شكي، فهل صلاتي صحيحة؟ أم باطلة؟","title":"شك هل سجد سجدة، أم سجدتين فما الحكم؟","answer":"الجواب: الواجب على من شك: هل سجد الثانية؟ أن يسجد الثانية، هذا الواجب: أن يسجد الثانية، ثم يسجد للسهو بعد ذلك، أما هذه التي شكت في السجدة الثانية، ولم تسجد عليها أن تعيد الصلاة، عليها أن تعيد الصلاة؛ لأنها تركت ركنًا متيقنًا مع الشك، فلابد من السجدتين، الواجب عليها إذا شكت أن تأتي بالسجدة الثانية، وتسجد للسهو قبل أن تسلم، تجمع بين الأمرين، تأتي بالسجدة حتى تتيقن أنها سجدت سجدتين، ثم مع ذلك تسجد للسهو من أجل الشك، هذا هو الواجب عليها، ولا يجوز لها التساهل في هذا. إلا إذا كانت عندها وساوس؛ فالأصل السلامة، إذا كان عندها وساوس؛ لا شيء عليها، أما إذا كان لا، سهو عارض؛ فالواجب عليها أن تسجد السجدة الثانية، ثم تسجد للسهو، أما من بلي بالوساوس الكثيرة؛ فعليه أن يطرحها، ويبني على ظنه، ولا يضر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14752/شك-هل-سجد-سجدة-ام-سجدتين-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57924.mp3","categories":["سجود السهو","الركوع والسجود"]},{"id":16189,"question":"عند الرفع من الركوع هل من اللازم قول: الله أكبر، أم أنه لا يجوز في هذا الموضع؟ جزاكم الله خيرًا.","title":"الذكر الوارد عند الرفع من الركوع","answer":"الجواب: عند الرفع من الركوع إن كان إمامًا، أو منفردًا يقول: سمع الله لمن حمده، إذا كان إمامًا، أو منفردًا، أما إذا كان مأمومًا؛ فإنه يقول عند الرفع: ربنا ولك الحمد، أو اللهم ربنا ولك الحمد، كما جاء في الأحاديث الصحيحة عن رسول الله، عليه الصلاة والسلام. والإمام يقول بعد الرفع بعدما يقول: سمع الله لمن حمده، يقول: ربنا ولك الحمد، والمنفرد كذلك بعدما يقول: سمع الله لمن حمده، يقول: ربنا ولك الحمد. أما المأموم فعند الرفع يقول: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، أربع صفات: ربنا لك الحمد، ربنا ولك الحمد، اللهم ربنا لك الحمد، اللهم ربنا ولك الحمد، كلها صفات جاءت في الأحاديث عند الرفع في حق المأموم.  أما الإمام، والمنفرد فإنه يقول هذا الكلام بعد الانتصاب، بعدما يقول: سمع الله لمن حمده، يأتي بربنا ولك الحمد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14869/الذكر-الوارد-عند-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80608.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16206,"question":"عند الرفع من الركوع هل من اللازم قول: الله أكبر، أم أنه لا يجوز في هذا الموضع؟ جزاكم الله خيرًا.","title":"الذكر الوارد عند الرفع من الركوع","answer":"الجواب: عند الرفع من الركوع إن كان إمامًا، أو منفردًا يقول: سمع الله لمن حمده، إذا كان إمامًا، أو منفردًا، أما إذا كان مأمومًا؛ فإنه يقول عند الرفع: ربنا ولك الحمد، أو اللهم ربنا ولك الحمد، كما جاء في الأحاديث الصحيحة عن رسول الله، عليه الصلاة والسلام. والإمام يقول بعد الرفع بعدما يقول: سمع الله لمن حمده، يقول: ربنا ولك الحمد، والمنفرد كذلك بعدما يقول: سمع الله لمن حمده، يقول: ربنا ولك الحمد. أما المأموم فعند الرفع يقول: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، أربع صفات: ربنا لك الحمد، ربنا ولك الحمد، اللهم ربنا لك الحمد، اللهم ربنا ولك الحمد، كلها صفات جاءت في الأحاديث عند الرفع في حق المأموم.  أما الإمام، والمنفرد فإنه يقول هذا الكلام بعد الانتصاب، بعدما يقول: سمع الله لمن حمده، يأتي بربنا ولك الحمد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14869/الذكر-الوارد-عند-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80608.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16216,"question":"من نسي الركوع فماذا يفعل، ولا سيما إذا ذكر قبل أن يسجد؟","title":"حكم من نسي الركوع وذكر قبل أن يسجد","answer":"الجواب: إذا ذكر الركوع يقوم، إنْ كان قد سجد يقوم يقف، ويركع، وإن كان قد سجد كذلك يقوم، ويأتي بالركوع، ثم ينتصب، ثم يسجد بعد ذلك، وعليه سجود السهو قبل أن يسلم، وإن سجد بعد السلام؛ فلا بأس، لكن الأفضل في مثل هذا قبل السلام. فالمقصود: أنه إذا هوى للسجود، ثم تذكر أنه لم يركع؛ ينتصب ويركع، وإن كان ذكر في السجود، أو وهو جالس للتشهد؛ يقوم ويأتي بالركوع، ثم يرفع، ثم يسجد، ثم يكمل، ثم يسجد للسهو، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14887/حكم-من-نسي-الركوع-وذكر-قبل-ان-يسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71307.mp3","categories":["سجود السهو","الركوع والسجود"]},{"id":16227,"question":"المستمعة أسماء محمود عثمان مقيمة في المملكة تقول: أريد أن أعرف دعاء السجود الخاص بالسجود؟ وهل هناك دعاء للركوع؟ جزاكم الله خيرًا.","title":"أدعية الركوع والسجود","answer":"الجواب: السجود يدعو فيه المؤمن بما يسر الله له، السجود يدعو فيه المؤمن والمؤمنة بما يسر الله من الدعوات الطيبة، ولو لم تنقل عن النبي ﷺ، ومن دعاء النبي ﷺ: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره ثبت عنه أنه كان يدعو بهذا في السجود -عليه الصلاة والسلام-: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره وإذا دعا الإنسان في السجود بغير هذا، مثل: اللهم يا مقلب القلوب ثبت قلبي على دينك، ويا مصرف القلوب صرف قلبي على طاعتك اللهم إنك عفو، تحب العفو فاعف عني اللهم اغفر لي، ولوالدي -إذا كان والداه مسلمين- اللهم اغفر لي ولوالدي، ولجميع المسلمين، اللهم أصلح قلبي وعملي، وما أشبه ذلك من الدعوات الطيبة. ويستحب أن يقول في الركوع والسجود: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي فهو تعظيم معه دعاء يقال في الركوع والسجود: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي ولكن الركوع لا يدعى فيه إلا بهذا فقط، الركوع محل تعظيم، يقول النبي ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء؛ فقمن أن يستجاب لكم يعني: فحري أن يستجاب لكم. لكن إذا قال في الركوع: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي فهذا مشروع، كان يفعله النبي ﷺ وهذه الدعوة تابعة (اللهم اغفر لي) تابعة للتعظيم؛ فلا حرج فيها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14914/ادعية-الركوع-والسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75119.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16228,"question":"تقول: سمعت بأنه لا تجوز قراءة القرآن أثناء السجود، فهل يجوز قراءة الأدعية الموجودة في القرآن مثال: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201]؟","title":"حكم الدعاء بالأدعية الواردة في القرآن في السجود","answer":"الجواب: الرسول ﷺ نهى عن قراءة القرآن في الركوع والسجود، لكن إذا دعا الإنسان بالدعوات القرآنية من غير قصد للقراءة؛ فلا حرج، مثل الآية التي ذكرت السائلة: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] ومثل قوله سبحانه: رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8] لا حرج في ذلك بنية الدعاء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14909/حكم-الدعاء-بالادعية-الواردة-في-القران-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75117.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16403,"question":"عبدالله أبو عمر من الأردن، يقول: سماحة الشيخ! خلال أيام الشتاء أشعر بالبرد الشديد في يدي، هل يجوز لي أن أرتدي قفازات من الصوف في يدي، وأنا أصلي بهما، هل هذا ينافي السجود على السبعة أعضاء، ومنها اليدين؟","title":"هل الصلاة بالقفازين ينافي السجود على الأعضاء السبعة؟","answer":"الجواب: لا حرج في ذلك، ولو جعلت القفازين مثلما تجعل في رجليك الخفين، لا حرج والحمد لله، إذا جعلت القفازين في يديك للدفء، أو جعلتها في غترتك، شماغك، أو غيرها، أو في بشتك، وسجدت عليه؛ فلا بأس، الأمر واسع الحمد لله، كان الصحابة -رضي الله عنهم وأرضاهم- إذا اشتد عليهم حر الأرض سجدوا على ثيابهم، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15107/هل-الصلاة-بالقفازين-ينافي-السجود-على-الاعضاء-السبعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58121.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16743,"question":"من العراق رسالة بعث بها المستمع حامد يونس إبراهيم من الموصل يقول: عند الركوع هل وضع اليدين أصح من وضع الركبتين أولًا، أو بالعكس؟ جزاكم الله خيرًا.","title":"السنة تقديم الركبتين عند الهوي للسجود","answer":"الجواب: الأصح، والأفضل أن يضع ركبتيه أولًا، كان النبي ﷺ يضع ركبتيه ثم يديه ﷺ وينهى عن بروك كبروك البعير، والبعير إذا برك يقدم يديه، فالسنة أن تقدم ركبتيك لا يديك، والأحاديث في الحقيقة متفقة، لا مختلفة، وهي السجود على الركبتين، ثم اليدين، ثم الجبهة والأنف، والرفع يرفع رأسه، ثم يديه، ثم ركبتيه. نعم، هذا هو الأرجح، والأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15492/السنة-تقديم-الركبتين-عند-الهوي-للسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_821/nour_82105.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16744,"question":"من العراق رسالة بعث بها المستمع حامد يونس إبراهيم من الموصل يقول: عند الركوع هل وضع اليدين أصح من وضع الركبتين أولًا، أو بالعكس؟ جزاكم الله خيرًا.","title":"السنة تقديم الركبتين عند الهوي للسجود","answer":"الجواب: الأصح، والأفضل أن يضع ركبتيه أولًا، كان النبي ﷺ يضع ركبتيه ثم يديه ﷺ وينهى عن بروك كبروك البعير، والبعير إذا برك يقدم يديه، فالسنة أن تقدم ركبتيك لا يديك، والأحاديث في الحقيقة متفقة، لا مختلفة، وهي السجود على الركبتين، ثم اليدين، ثم الجبهة والأنف، والرفع يرفع رأسه، ثم يديه، ثم ركبتيه. نعم، هذا هو الأرجح، والأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15492/السنة-تقديم-الركبتين-عند-الهوي-للسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_821/nour_82105.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":16879,"question":"ماهي الأذكار الصحيحة داخل الصلاة، وبعد التسليم؟ جزاكم الله خيرًا.","title":"ما الأذكار التي تقال في الصلاة؟","answer":"الجواب: داخل الصلاة يشرع له الاستفتاح في أولها بعدما يكبر يقول: الله أكبر التكبيرة الأولى -وهي التي تسمى تكبيرة الإحرام- يستفتح كما كان النبي يفعل هذا -عليه الصلاة والسلام- ومن ذلك: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك هذا يسمى الاستفتاح، وهو أخصرها.  ومن ذلك: ما كان يفعله النبي ﷺ أيضًا اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد وهناك استفتاحات أخرى صحيحة موجودة في كتب الحديث: كالمنتقى، وبلوغ المرام، والبخاري، وصحيح مسلم .. إلى غير ذلك. لكن هذان الاستفتاحان من أخصر الاستفتاحات. ثم يقول: أعوذ بالله من الشيطان الرجيم، بسم الله الرحمن الرحيم، ثم يقرأ الفاتحة (الحمد) ثم يقرأ ما تيسر معه إن كان إمامًا، أو منفردًا، أو مأمومًا في السرية صلاتي الظهر والعصر، وإن كان مأمومًا في الجهرية؛ قرأ الفاتحة فقط، وسكت، ينصت لإمامه، يستمع للإمام. وإذا كبر للركوع يقول: سبحان ربي العظيم سبحان ربي العظيم يكررها ثلاثًا، أو أكثر، والواجب مرة، سبحان ربي العظيم مرة واحدة الواجب، والتكرار مستحب، ويقول بعد ذلك: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي مستحب أيضًا، ويقول: سبوح قدوس، رب الملائكة والروح هذا مستحب أيضًا في الركوع، والسجود. وإذا رفع -كان إمامًا أو منفردًا- يقول: سمع الله لمن حمده وإن كان مأمومًا يقول: ربنا ولك الحمد أو اللهم ربنا لك الحمد حمدًا كثيرًا طيبًا مباركًا فيه، ملء السموات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد وإن زاد أهل الثناء والمجد، أحق ما قال العبد، وكلنا لك عبد، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد كان أفضل؛ لأنه ثابت عن النبي ﷺ وإذا اقتصر على ما تقدم قوله: وملء ما شئت من شيء بعد كفى، والواجب ربنا ولك الحمد أو اللهم ربنا لك الحمد والبقية سنة ومستحب. المقدم: جزاكم الله خيرًا. الشيخ: وهكذا في السجود يكبر، بعدما يكبر للسجود يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، في الركوع يقول: سبحان ربي العظيم في السجود، سبحان ربي الأعلى، سبحان ربي الأعلى، ويقول مع هذا: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي سبوح قدوس رب الملائكة والروح ويدعو في السجود ما تيسر، يدعو، مشروع في السجود الدعاء منها: اللهم اغفر لي ذنبي كله.. دقه وجله، وأوله وآخره، وعلانيته وسره. يقول النبي ﷺ: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء ويقول ﷺ: «أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء؛ فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، ويدعو بما يسر الله له من خير الدنيا والآخرة في السجود، في الفرض، والنفل للحديثين المذكورين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15634/ما-الاذكار-التي-تقال-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76416.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":17366,"question":"ماذا يقول المسلم بين السجدتين في الصلاة، سواء كانت فرضًا، أم نفلًا؟","title":"ما يقوله المصلي بين السجدتين في الصلاة","answer":"الجواب: يقول: رب اغفر لي، رب اغفر لي، اللهم اغفر لي، وارحمني، واهدني، واجبرني، وارزقني، يكثر من ذلك: رب اغفر لي، رب اغفر لي، اللهم اغفر لي، وارحمني، واهدني، هكذا كان النبي يعمل ﷺ. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16200/ما-يقوله-المصلي-بين-السجدتين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59326.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":17651,"question":"سماحة الشيخ حفظكم الله، هذا سائل يقول: في حديث ما معناه بأنه عند السجود كان يفتح بين أصابع رجليه، ما معنى الفتح وكيفيته، وكذلك عند التشهد الأخير؟","title":"وضعية أصابع اليدين والرجلين عند الركوع والسجود","answer":"الجواب: يعتمد على بطون أصابع رجليه مفتوحتان، يعتمد على أصابع رجليه حين السجود، ويعتمد على كفيه حين السجود كذلك، فالأصابع في الكفين مقبوضة إذا لصق بعضها ببعض مادًا لها، أما الرجلين يعتمد على بطون أصابعها وهو موقف لها، ويعتمد على بطون الأصابع. نعم.","link":"https://binbaz.org.sa/fatwas/16580/وضعية-اصابع-اليدين-والرجلين-عند-الركوع-والسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59423.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":17792,"question":"في ثاني أسئلة السائلة أم خالد من الباحة تقول سماحة الشيخ: في أثناء السجود وبعد التسبيح أدعو بأدعية عارضة أي: من الحياة، مثل أن أدعو بالمغفرة لي ولوالدي أو أن يحفظ لي...الشيخ: أعد أعد.المقدم: تقول السائلة: في أثناء السجود وبعد التسبيح أدعو بأدعية عارضة أي: من الحياة، مثل أن أدعو بالمغفرة لي ولوالدي، أو أن يحفظ لي أولادي.. وهكذا، فهل هذا يبطل الصلاة؛ لأنه كلام خارج عن أصل الصلاة؟","title":"حكم الدعاء بأمر دنيوي أثناء السجود","answer":"الجواب: كله طيب، الدعاء في السجود طيب قال النبي ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم يعني: فحري أن يستجاب لكم، وقال عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء وهذا يعم دعاء الدنيا ودعاء الآخرة، وكان يقول في سجوده عليه الصلاة والسلام: اللهم اغفر لي ذنبي كله دقه وجله، وأوله وآخره، وعلانيته وسره، ويقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي.\nفإذا دعا الإنسان في السجود فيما يتعلق بالآخرة والدنيا فلا بأس، اللهم اغفر لي وارحمني، اللهم أصلح ذريتي، اللهم أصلح زوجي، اللهم اغفر لوالدي، اللهم ارزقني رزقًا حلالًا.. إلى غير هذا نعم، كله طيب في السجود. نعم.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16786/حكم-الدعاء-بامر-دنيوي-اثناء-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77813.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":17802,"question":"من أسئلة السائل أبو عبد الله من القصيم يقول: إذا دعا الإنسان في الركوع ناسيًا، هل يجوز له ذلك؟","title":"حكم الدعاء في الركوع","answer":"الجواب: لا حرج عليه، إذا دعا لا حرج عليه، لكن لا يتعمد ذلك، يقول النبي ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فالدعاء يكون في السجود، والركوع يكون فيه تعظيم الرب: (سبحان ربي العظيم، سبحان ربي العظيم، سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، سبوح قدوس رب الملائكة والروح)، فهذا هو المشروع في الركوع، قوله: (سبحانك اللهم ربنا وبحمدك اللهم اغفر لي)، هذه دعوة تابعة للتسبيح، فيكثر من التسبيح، أما الدعاء فيكثر منه في السجود محله السجود. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16784/حكم-الدعاء-في-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59713.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18157,"question":"هذه سائلة من الرياض ذكرت هذا الرمز تقول: نعلم وجوب السجود على الأعضاء السبعة، ولكنني يا سماحة الشيخ أحيانًا لا أنتبه أو لا أتنبه بعدم سجودي على الأعضاء السبعة كاملة؛ لوجود حائل لم أزله إلا بعد الانتهاء من السجود، فهل علي شيء من ذلك؟","title":"حكم السجود على الأعضاء السبعة","answer":"الجواب: الواجب السجود على الأعضاء السبعة، لا يصح السجود إلا بذلك، فإذا كان السجود على فراش أو على بساط، أو على غير ذلك؛ فلا بأس ما يضر، ما هو بلزوم يباشر الأرض، إذا سجد على مطرحة، أو على زولية، أو على بساط، أو على غيرها؛ لا بأس. أما إذا رفع أحد الأعضاء سجد على ستة، أو خمسة؛ ولم يضع يده على الأرض أو يديه أو وجهه ما يصح السجود، لا بد أن يضع وجهه على الأرض، سواء الأرض فيها بساط، أو ما فيها بساط للأرض جبهته، وأنفه، وكفيه على الأرض، قدميه، ركبتيه؛ هذه السبعة، فإذا رفع يده، أو وجهه، ولم يسجد ما يسمى ساجد، حتى يضع وجهه على الأرض ويديه على الأرض، وركبتيه على الأرض، وقدميه على الأرض .. على بطون أصابعه، هذا هو السجود الشرعي. فلو سجد وهو رافع يده أو رجله لم يصح السجود، أو سجد في الهواء وهو قادر على الأرض ما هو بمريض، يستطيع السجود على الأرض، وسجد ولكن لم يصل وجهه إلى الأرض؛ ما يصح السجود. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/17207/حكم-السجود-على-الاعضاء-السبعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78123.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18175,"question":"ما حكم من يصلي على أنفه، ولم يمكن جبهته؟ هل تبطل الصلاة؟","title":"حكم صلاة من يسجد على أنفه ولا يمكن جبهته","answer":"الجواب: نعم، ما تصح الصلاة، ما يصح السجود، إذا تعمد ذلك يكون السجود باطلًا، أما إن كان ناسيًا، فيعيد السجدة، يعيد السجدة إن كان مازال في السجدة، يعيدها، وإن كان قد قام، وقرأ، تبطل الركعة، ويأتي بركعة بدلًا منها؛ لأن هذه الركعة بطلت ببطلان السجود، لابد أن يسجد على الجبهة والأنف جميعًا، أما إذا تنبه في الحال؛ فإنه يعيد السجود، يعيد السجود في الحال قبل أن يقوم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17215/حكم-صلاة-من-يسجد-على-انفه-ولا-يمكن-جبهته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73110.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18305,"question":"يقول السائل هذا يا سماحة الشيخ! ما حكم من يصلي وهو واضع العمامة على الجبهة، حتى تصل إلى حاجب العين، أي: أنه مغطي موضع السجود وهو الجبهة؟","title":"حكم السجود على كور العمامة","answer":"الجواب: الصلاة صحيحة، لكن الأفضل أن يرفع العمامة ويسجد على المصلى، ولو سجد على عمامته أو على طرف بشته لا بأس، لكن الأفضل أن تكون جبهته على المصلى هذا هو الأفضل.","link":"https://binbaz.org.sa/fatwas/17353/حكم-السجود-على-كور-العمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91302.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18564,"question":"أخونا يسأل هذا السؤال ويقول: أيهما أرجح: الهوى إلى السجود باليدين، أم بالركبتين؟","title":"الأرجح في كيفية الهوي إلى السجود","answer":"الجواب: هذا محل اختلاف بين العلماء، والأفضل والأرجح الهوي بالركبتين ثم اليدين، ركبتيه، يعني: يقدم ركبتيه ثم يديه ثم جبهته وأنفه، هذا هو الأفضل على حديث وائل بن حجر وما جاء في معناه، ومن قدم يديه فالأمر واسع -إن شاء الله-؛ لأن فيه حديث أبي هريرة أيضًا، ولكن الصواب أنه يقدم ركبتيه، ثم يديه ثم جبهته وأنفه. وأما حديث أبي هريرة الذي فيه: وليضع يديه قبل ركبتيه فهو فيه انقلاب كما حققه بعض أهل العلم؛ لأن أول الحديث يقول ﷺ: لا يبرك أحدكم كما يبرك البعير  والبعير يقدم يديه، فإذا قدمنا أيدينا صرنا مشابهين للبعير، فيكون آخر الحديث يخالف أوله، فيكون الصواب: (وليضع ركبتيه قبل يديه) على حديث وائل وعلى موافقة صدر الحديث، فحصل انقلاب (فليضع يديه قبل ركبتيه). المقصود: أن الأرجح أن يقدم ركبتيه قبل يديه، وأن الأرجح في حديث أبي هريرة أنه موافق لحديث وائل، وأن ما في آخره من ذكر اليدين قبل الركبتين انقلاب من بعض الرواة، وهو الأقرب والأظهر حتى لا يخالف آخر الحديث أوله، وحتى تجتمع الأحاديث عن النبي ﷺ وهذا هو الذي عليه جمهور أهل العلم وأكثر أهل العلم. ومن ترجح عنده تقديم اليدين واجتهد في ذلك فلا ينبغي أن ينكر عليه، ينبغي في هذا عدم التشديد، وعدم النزاع والخلاف، فالمؤمن يتحرى الحق، فالأرجح والأظهر والأقرب أن يقدم ركبتيه ثم يديه ثم جبهته مع أنفه، هذا في السجود، وعند الرفع يبدأ بالوجه ثم اليدين ثم ينهض على ركبتيه، هذا هو الأفضل، وهذا هو الذي به الجمع بين الأحاديث، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17678/الارجح-في-كيفية-الهوي-الى-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_917/nour_91706.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18629,"question":"هذا سائل للبرنامج نور الدين له مجموعة من الأسئلة، يقول في السؤال الأول: ما حكم السجود على العمامة؟ وهل يجوز السجود عليها؟","title":"حكم السجود على العمامة","answer":"الجواب: الأفضل يسجد على المصلى، هذا الأفضل، يسجد على المصلى لا على العمامة، ولا..، بل على المصلى، سواء المصلى سجادة أو بساط، أو حصباء، أو رمل؛ يسجد مع الناس على المصلى، فلو سجد على أطراف العمامة ما يضر، لو وضع جبهته على أطراف العمامة أو الغترة، أو بشت، أو غيره ما يضر، لكن كونه يسجد على المصلى الذي يصلي عليه الناس، أو مصلاه الذي هو يصلي عليه في بيته أفضل، يباشر المصلى بجبهته وأنفه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17743/حكم-السجود-على-العمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78712.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18656,"question":"من القصيم هذه رسالة بعثت بها إحدى الأخوات تقول المرسلة: (ع. ل. هـ) أختنا تسأل وتقول: لقد كنت في صلاتي أثناء الرفع من الركوع أقول: ربنا ولك الحمد، دون أن أقول: سمع الله لمن حمده، ولكنني بعد ذلك سمعت أنه لا يجوز ذلك، بل لا بد أن أقول: سمع الله لمن حمده، فهل علي إثم وذنب في صلواتي التي مضت، مع العلم بأنني لم أكن أعلم بأن قول: (سمع الله لمن حمده) واجب في الصلاة؟ وإذا كان علي شيء فماذا أفعل؟أفيدوني، جزاكم الله خيرًا.","title":"حكم ترك: (سمع الله لمن حمده) بعد الرفع من الركوع","answer":"الجواب: نرجو ألا يكون عليك شيء؛ لأجل الجهل، وعليك مع ذلك الاستغفار والتوبة والندم على ما حصل من التساهل، وعدم السؤال؛ لأن الواجب على من جهل شيئًا أن يسأل أهل العلم في صلاته وغيرها، وما مضى صحيح والحمد لله، وعليك في المستقبل أن تقولي: (سمع الله لمن حمده) عند الرفع من الركوع. وهكذا الإمام وهكذا المنفرد من الرجال، كل واحد يقول: سمع الله لمن حمده.  أما المأموم فيقول: ربنا ولك الحمد، هذا هو الصواب، وليس عليه أن يقول: (سمع الله لمن حمده) ولا يشرع له ذلك، إنما هذا من شأن الإمام والمنفرد من الرجال والنساء، عند الرفع يقول: سمع الله لمن حمده، وعند الاستواء يقول: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، وما مضى نسأل الله أن يعفو عنا وعنك، والصلاة صحيحة -إن شاء الله- من أجل الجهل، ولكن في المستقبل عليك أن تجتهدي في ذلك، وأن تستمري عليه، وأن لا تتركي هذه الكلمة: (سمع الله لمن حمده) إذا كنت منفردة، أما مع الإمام فتقولي: (ربنا ولك الحمد) إذا صليت مع الإمام تقولي: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17766/حكم-ترك-سمع-الله-لمن-حمده-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91906.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":18747,"question":"خالد سليمان مصري، ويعمل في دولة قطر، أرسل إلى البرنامج بمجموعة من الأسئلة، يبدأ هذه الرسالة بهذا السؤال ويقول: سماحة الشيخ، هل تجوز الصلاة على النبي ﷺ في السجود أو في الصلاة؟","title":"حكم الصلاة على النبي ﷺ في السجود","answer":"الجواب: نعم، إذا صلى على النبي ﷺ في السجود قبل الدعاء مستحب، يحمد الله، ويصلي على النبي ﷺ ويدعو في السجود، وفي آخر الصلاة قبل أن يسلم، وفي دعواته الأخرى خارج الصلاة يحمد الله، ويصلي على النبي ﷺ ويدعو؛ لقوله ﷺ في حديث فضالة بن عبيد: إذا صلى أحدكم فليبدأ بتحميد ربه، والثناء عليه، ثم يصلي على النبي ﷺ ثم يدعو بما شاء هذا هو السنة؛ أن يبدأ بالحمد والثناء والصلاة على النبي ﷺ ثم يدعو، ولو في السجود، أو في آخر الصلاة، أو في أي وقت آخر غير الصلاة، نعم.","link":"https://binbaz.org.sa/fatwas/17859/حكم-الصلاة-على-النبي-ﷺ-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78911.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19132,"question":"من صديق البرنامج كما وصف نفسه المستمع (ع. ع. س) من ليبيا رسالة وضمنها جمعًا من الأسئلة، في أحدها يقول: عندنا في المسجد إمام، وهذا الإمام يصلي بنا وهو سريع في صلاته، وعند السجود يسبق اليدين قبل الركبتين، ونحن مجموعة شباب نخالفه في سجوده فنسبق الركبتين قبل اليدين بدليل: \"لا تشبهوا سجودكم بالبعير\"، فهل هذا السجود صحيح؟ وجهونا مأجورين جزاكم الله خيرًا.","title":"حكم تقديم اليدين على الركبتين حال الهوي إلى السجود","answer":"الجواب: سجودكم جميعًا صحيح، سجوده صحيح، وسجودكم صحيح، والحمد لله، لكن الأفضل مثلما فعلتم تقديم الركبتين على اليدين كما جاء في حديث وائل وغيره وهو موافق لحديث أبي هريرة الذي فيه النهي عن البروك كبروك البعير؛ لأن بروك البعير يقدم يديه، فالسنة أن يقدم الركبتان، أن تقدم الركبتان لأنهما في الرجلين قبل اليدين. وذهب بعض أهل العلم إلى تقديم اليدين قبل الركبتين؛ لأن في حديث أبي هريرة : وليضع يديه قبل ركبتيه، وتأولوا ذلك على أن بروك البعير على ركبتيه وهما في يديه، فإذا قدم المصلي يديه فقد خالف البعير، وليس الأمر كذلك، الصحيح أن بروك الإنسان على يديه هو الذي يشبه البعير، ويخالف أول الحديث لا يبرك كما يبرك البعير ويخالف حديث وائل: \"رأيت النبي ﷺ إذا سجد وضع ركبتيه قبل يديه\" هذا هو الأفضل وهذا هو الأشهر. ومن اعتقد ما دل عليه آخر حديث أبي هريرة: وليضع يديه قبل ركبتيه من اعتقد هذا ووضع يديه قبل ركبتيه عن اجتهاد منه فلا حرج عليه، والله يغفر للجميع، لكن الأفضل هو تقديم الركبتين قبل اليدين هذا هو الأرجح، وهذا هو الأفضل، ومن قدم يديه قبل ركبتيه معتقدًا أن هذا هو الأفضل حسب اجتهاده وعلمه فلا شيء عليه، المصيب له أجران، والمخطي له أجر واحد، والحمد لله، هذا كله إذا كان يستطيع تقديم الركبتين، أما إذا كان عاجزًا لكبر سنه، أو مرضه؛ فإنه يقدم يديه، ولا شيء عليه، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18348/حكم-تقديم-اليدين-على-الركبتين-حال-الهوي-الى-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79805.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19194,"question":"رسالة من أحد الإخوة المستمعين يقول اسمي هشام عبدالرحمن من السودان الخرطوم، أخونا له عدد من الأسئلة من بينها سؤال يقول: قد ذكرت -يحفظكم الله- أن صفة صلاة النبي ﷺ أن ينزل الإنسان من الركوع إلى السجود على ركبتيه، وينهض إلى الركعة برفع يديه قبل ركبتيه، لكن بعض الباحثين ذكر عكس ذلك، فأي القولين نعتمد، وبأيهما نعمل؟ جزاكم الله خيرًا.","title":"الصواب في كيفية الهوي في السجود في الصلاة","answer":"الجواب: للعلماء قولان في المسألة -رحمهم الله- منهم من رجح أنه ينزل بركبتيه، ثم يديه، ثم جبهته وأنفه؛ لما روى أهل السنن عن وائل بن حجر  عن النبي ﷺ أنه رأى النبي ﷺ إذا سجد قدم ركبتيه على يديه، وله شاهد من حديث أنس أيضًا عند الحاكم وغيره، وقالوا: هذا هو الأرفق بالمصلي وهو الأبعد عن مشابهة الحيوان؛ لأن الحيوان كالبعير ينزل على يديه ثم مؤخره بعد ذلك، وقالوا: هو الموافق لحديث أبي هريرة  عن النبي ﷺ أنه قال: لا يبرك أحدكم كما يبرك البعير فإن بروك البعير يقدم يديه، فإذا قدم رجليه لم يشبه البعير. أما قوله في آخره: وليضع يديه قبل ركبتيه فقال بعضهم: لعله مقلوب، وأن الصواب وليضع ركبتيه قبل يديه حتى يتفق أوله مع آخره، أول الحديث مع آخر الحديث، وحتى يتفق مع حديث وائل بن حجر وأنس وما جاء في معناهما، وهذا هو الأصح والأرجح، وبذلك تتفق الأحاديث ولا يقع بينها خلاف، فالنهي عن بروك كبروك البعير يوافق حديث وائل في تقديم الركبتين ثم اليدين بعد ذلك في السجود. أما زيادة: وليضع يديه قبل ركبتيه فهي تخالف أول الحديث، وتخالف حديث وائل؛ لأنه إذا وضع يديه قبل ركبتيه شابه البعير في نزوله على مقدمه، هذا هو الأرجح. وقال آخرون من أهل العلم: لفظة: وليضع يديه صريحة تدل على أنه يقدم يديه على ركبتيه، وبهذا خالفوا حديث وائل وهو حديث لا بأس به حديث حسن جيد، مع أنه موافق لأول حديث أبي هريرة ولمقدمه وصدره. والصواب عندي والأرجح عندي أنه يقدم ركبتيه ثم يديه، ثم جبهته وأنفه على ما في حديث وائل، وعلى مقتضى أول حديث أبي هريرة وصدره، وزيادة: وليضع يديه قبل ركبتيه هذه إما إدراج من بعض الرواة، وإما حصل فيها انقلاب والصواب: وليضع ركبتيه قبل يديه حتى يتفق أوله مع آخره، وحتى يتفق مع حديث وائل وما جاء في معناه، والأمر في هذا واسع والحمد لله كله سنة، لكن هذا هو الأفضل وهذا هو الأرجح، إلا من عجز ككبير السن والمريض هذا يقدم يديه؛ لأنه محتاج إلى ذلك ولا بأس بذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18424/الصواب-في-كيفية-الهوي-في-السجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_799/nour_79904.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19294,"question":"المستمعة (ع. س) من الرياض بعثت برسالة وضمنتها عدداً من الأسئلة، عرضنا معظم أسئلتها في حلقات مضت، وبقي لها في هذه الحلقة سؤالان، السؤال الأول يقول: هل يجوز أن نصلي على النبي ﷺ في السجود؟ جزاكم الله خيرًا.","title":"حكم الصلاة على النبي صلى الله عليه وسلم في السجود","answer":"الجواب: نعم، نصلي عليه هذا دعاء، الصلاة على النبي ﷺ دعاء، والنبي عليه الصلاة والسلام قال: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء رواه مسلم في الصحيح، وقال عليه الصلاة والسلام: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم يعني: فحري أن يستجاب لكم، رواه مسلم أيضًا في صحيحه. وكان النبي يدعو في سجوده عليه الصلاة والسلام، ويلح في الدعاء، فإذا حمدت الله في سجودك، وصليت على النبي ﷺ فهذا من أسباب الإجابة: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك اللهم اغفر لي هذا ثناء على الله، سبوح قدوس رب الملائكة والروح، هذا يقال في السجود وفي الركوع جميعًا، ويختص السجود بـ سبحان ربي الأعلى، والركوع يختص بـ سبحان ربي العظيم، أما سبوح قدوس رب الملائكة والروح هذا في السجود والركوع جميعًا، وهكذا سبحانك اللهم ربنا وبحمدك اللهم اغفر لي هذا يقال في السجود والركوع جميعًا. وإذا صليت على النبي ﷺ بعد ذلك في السجود قلت: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وآل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد ثم دعوت الله بعد ذلك هذا من أسباب الإجابة، دعوت للنبي ﷺ هذا قربة منك تتقرب بها إلى الله، وإحسان لنبيك عليه الصلاة والسلام؛ تدعو له في الصلاة أن الله يثني عليه ويرحمه، وهكذا لو قلت: اللهم صل وسلم على الرسول باختصار، اللهم صل وسلم على رسول الله مختصرًا كفى، وإن كملتها كما جاءت في الأحاديث الصحيحة فهو أفضل وأكمل. ثم تدعو بما تشاء: اللهم اغفر لي ذنبي كله دقه وجله، وأوله وآخره، وعلانيته وسره هذا من دعاء النبي ﷺ في السجود كان يدعو بهذا الدعاء عليه الصلاة والسلام، وإذا دعوت بغير هذا: اللهم إني أسألك رضاك والجنة وأعوذ بك من سخطك والنار، اللهم أصلح قلبي وعملي، وارزقني الفقه في ديني، رب زدني علمًا، اللهم اجعلني من الهداة المهتدين، اللهم اغفر لي ولوالدي ولجميع المسلمين، وما أشبهه تدعو ربك تسأل ربك، اللهم اشرح لي صدري، ويسر لي أمري، واجعلني مباركاً أينما كنت. اللهم أصلح أحوال المسلمين، اللهم أصلح ولاة المسلمين، اللهم وفقهم لما يرضيك ... إلى غير هذا من الدعوات الطيبة في سجودك، كل هذا مشروع وحري بالإجابة ولاسيما إذا كان معه التسبيح والتحميد، والصلاة على النبي ﷺ قل أن تدعوه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18457/حكم-الصلاة-على-النبي-صلى-الله-عليه-وسلم-في-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_800/nour_80005.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19442,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها بعضًا من الأسئلة، والمستمع هو العبد الله أبو عبد الرحمن الطاهر بن عثمان بن علي، أخونا يسأل عن التكبيرة في السجود متى تكون، هل عندما يكون قد سجد في الأرض، أو عندما يكون هاويًا إلى السجود؟","title":"وقت التكبير للسجود","answer":"الجواب: التكبير للسجود عند الهوي يكبر حال هويه إلى الأرض يقول: الله أكبر حين يشرع في الهوي ويقطعها قبل أن يصل إلى الأرض، وعند الرفع كذلك إذا رفع يكبر حين رفعه وينتهي قبل استتمامه قائمًا، وهكذا إذا كان جالسًا إذا رفع من السجدة الأولى كبر حين رفعه من السجدة الأولى قبل أن يستتم جالسًا هكذا المشروع يكبر حين الرفع وحين النزول للسجود، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18682/وقت-التكبير-للسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93807.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19446,"question":"في أثناء الصلاة وأنا أريد السجود هل أنزل باليدين أم أنزل بالركبتين؟","title":"مشروعية النزول على الركبتين عند الهوي إلى السجود","answer":"الجواب: الأفضل نزولك بالركبتين هذا هو الأفضل كان النبي ﷺ إذا سجد سجد على ركبتيه، ثم يديه، ثم جبهته وأنفه إلا إذا كان هناك عجز كمرض أو كبر سن فلا بأس أن تسجد على يديك أولًا وتنهض عليهما للعجز والضعف، وذهب بعض أهل العلم إلى أنه يسجد على يديه مطلقًا ولكنه قول مرجوح. والصواب أن الأحاديث كلها في المعنى تدل على أنه يسجد على ركبتيه أولاً، ثم يديه، ثم جبهته وأنفه، هذا عند السجود، وعند الرفع يرفع رأسه أولاً ثم يديه ثم ركبتيه، إلا العاجز لمرض أو كبر سن فهذا لا بأس أن يسجد على يديه وينهض على يديه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18683/مشروعية-النزول-على-الركبتين-عند-الهوي-الى-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93808.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19566,"question":"هذه الأخت السائلة من القصيم البدائع (ع. م. ع) الحربي تقول: يا سماحة الشيخ! أنا أثناء صلاة التهجد أطيل في السجود وأحس بتعب في الأيدي والصدر، هل يجوز لي أن أضع مخدة تحت الصدر وأكواع اليدين؟","title":"حكم وضع مخدة تحت الصدر عند السجود لمن يطيله","answer":"الجواب: ما أعرف لهذا أصل، لكن المشروع عدم التكلف، لا تطيل في السجود حتى لا تكلف، أما وضعها هذه الأشياء ما أعرف لها أصلا ، لكن السنة عدم التكلف، تسجد حسب طاقتها ولا تتكلف. نعم.","link":"https://binbaz.org.sa/fatwas/18831/حكم-وضع-مخدة-تحت-الصدر-عند-السجود-لمن-يطيله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94720.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19574,"question":"في سؤالها الثاني تقول هذه السائلة من أبها: يا سماحة الشيخ في الصلاة عندما أرفع من الركوع، وأريد السجود؛ متى أكبر، هل عندما أنحني أم عندما أضع ركبتي على الأرض؟","title":"مشروعية التكبير عند الانحناء إلى السجود","answer":"الجواب: عند الانحناء، عند الانحناء تكبر، قبل أن تصل الأرض، تكبرين إذا انحنيت قبل الوصول إلى الأرض. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18837/مشروعية-التكبير-عند-الانحناء-الى-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94723.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]},{"id":19598,"question":"تقول السائلة: هل يشترط لدعاء السجود في صلاة الفريضة أن يبدأ بالحمد لله، والصلاة على النبي ﷺ؟","title":"حكم ابتداء الدعاء في الصلاة بالحمد لله والصلاة على النبي ﷺ","answer":"الجواب: لا ما هو بشرط، يدعو بما تيسر، وإن حمد الله، وصلى على النبي ﷺ فلا بأس، كله طيب، هذا من أسباب الإجابة، وإن دعا فقط ولم يحمد الله، ولم يصل على النبي ﷺ بل دعا وقال: «سبحان ربي الأعلى، سبحان ربي الأعلى» ودعا اللهم اغفر لي وارحمني، واهدني وارزقني، وعافني، اللهم أدخلني الجنة، وأنجني من النار، اللهم أصلح قلبي وعملي، اللهم اغفر لي ولوالدي كله طيب. المقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18859/حكم-ابتداء-الدعاء-في-الصلاة-بالحمد-لله-والصلاة-على-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94801.mp3","categories":["الأدعية والأذكار","التكبير والاستفتاح","الركوع والسجود"]}]
